[NativeLocalMapEU0]
moduleMatches = 0xB7E748DE

.origin = codecave

# Runtime data; no instance or host addresses are hard coded.
_mapState:
.int 0x4D415030 # MAP0 signature
.int 0 # independently allocated HUD map object
.int 0 # attached pane
.int 0 # original parent
.int 1 # user visibility
.int 0 # HUD ticks
.int 0 # marker updates
.int 255 # +1C native HUD fade only; artwork/markers have independent vertex alpha
_positionX:
.float -518.15 # compact: 24-unit left/bottom margins, half the previous spacing
_positionY:
.float -238.15
.int 0 # previous native buttons, +0x28
.int 0 # context allows map, +0x2C
.float -470.976 # zoom 3 X, +0x30: same 24-unit margins as compact
.float -190.976 # zoom 3 Y, +0x34
.float 0.64 # zoom 3 overall HUD scale, +0x38 (previous 0.8 * 0.8)

.int 0 # menu map object, read only, +0x3C
.int 0 # creation status, +0x40
.int -1 # actual island index, +0x44
.int -1 # save discovery result, +0x48
.int 0 # +4C geometry: 0 invalid, 1 valid, 2 discovered foot plan outside coverage
.int 0 # native parts descriptor (read-only), +0x50
.int 0 # slide initialized, +0x54
.int 1 # slide target visibility, +0x58
.int 0 # slide starting time-base tick, +0x5C
.int 0 # slide active, +0x60
.float 0.0 # current horizontal offset, +0x64
.float 0.0 # start offset, +0x68
.float 0.0 # destination offset, +0x6C
.float -244.7 # compact offscreen distance, +0x70; retain hidden edge clearance
.float -333.768 # large offscreen distance, +0x74; retain hidden edge clearance
.float 0.0 # visible offset, +0x78
.int 0 # authoritative native riding-boat result, +0x7C
.float 0.95 # compact overall HUD scale, +0x80 (previous 1.0 * 0.95)
.float 1.0 # native compact zoom, +0x84
.float 1.2 # native zoom range (2.2 - 1), +0x88
.float 2.2 # native large zoom, +0x8C
.int 0 # playing the owned enlarge clip backwards, +0x90

# Read only world/atlas geometry source; never claim the menu's pane or updater.
_rememberMap:
lis r12, _mapState@ha
addi r12, r12, _mapState@l
lwz r11, 4(r12)
cmpw r3, r11
beqlr # owned child updates once, at the end of the HUD tick
mflr r0
b 0x02639E04

# Hook at the end of the native HUD tick, after its children have been updated.
_hudTick:
mflr r0
stwu r1, -0x20(r1)
stw r0, 0x24(r1)
stw r30, 0x18(r1)
stw r31, 0x1C(r1)
mr r30, r3
bl _boatRestoreCompass
mr r3, r30
bl 0x02676D14 # displaced native HUD call
lis r31, _mapState@ha
addi r31, r31, _mapState@l
lwz r11, 0x14(r31)
addi r11, r11, 1
stw r11, 0x14(r31)
li r9, 0
stw r9, 0x2C(r31)
stw r9, 0x4C(r31)
bl 0x026396AC
stw r3, 0x7C(r31)
bl _boatBegin
bl _ensureOwnedMap
lwz r0, 0x40(r31)
cmpwi r0, 1
bne _tickDone
lwz r3, 4(r31)
cmpwi r3, 0
beq _tickDone
lwz r11, 4(r3)
lis r12, 0x100F
addi r12, r12, -0x676C # local-map vtable 0x100E9894
cmpw r11, r12
bne _invalidate

# Boat status has priority over HUD visibility, discovery and sector changes.
# 026396AC is the native map's own riding query (gameInfo+5CD8 bit 0x10000).
li r9, 0
# Native HUD context: pause/UI flag and heart visibility.
lbz r0, 0xA7(r30)
cmpwi r0, 0
bne _readButtons
lwz r8, 0x4C(r30)
lwz r8, 0(r8) # native hearts object
lwz r8, 0x44(r8)
lwz r8, 4(r8)
lwz r8, 0x0C(r8)
lwz r8, 0x14(r8) # N_All_00 of native hearts
lbz r0, 0x44(r8)
andi. r0, r0, 1
beq _readButtons
lbz r0, 0x45(r8)
cmpwi r0, 0
beq _readButtons
# CompassClock+60 is a clock/day-night flag, NOT the player's boat status.
# Live current stage, NOT the save's restart stage at world+0x50.
# Native stage code uses gameInfo+0x5134; +0x5140 is the next stage.
# The actual native map family takes priority over the stage name.
# Fortress outdoor dungeon rooms still belong to "sea"; never draw both plans.
# Resolve the current world feed, not the menu's selected chart or floor.
lis r8, 0x1020
lwz r8, -0x7CA4(r8)
cmpwi r8, 0
beq _readButtons
lwz r8, 0x218(r8)
cmpwi r8, 0
beq _readButtons
bl _refreshNativeMapFamily
li r9, 0 # the classifier clobbers volatile registers; preserve the closed gate
lwz r0, 0x60(r8) # native family: 0 marine, 1 dungeon, 2 neither
cmpwi r0, 0
bne _readButtons # no island fallback for a dungeon or unavailable family
lis r8, 0x1047 # EU v0 gameInfo singleton 0x1046F0B0
lwz r8, 0x41E4(r8) # current stage name at singleton+0x5134
li r9, 0
lis r0, 0x7365
ori r0, r0, 0x6100 # "sea\0"
cmpw r8, r0
bne _readButtons
li r9, 1
stw r9, 0x2C(r31)
lis r12, _boatState@ha
addi r12, r12, _boatState@l
stw r9, 8(r12)
bl _selectWorldMap
lwz r9, 0x2C(r31)

_readButtons:
lis r8, 0x101F
lwz r8, 0x50A0(r8)
lwz r8, 0x124(r8)
lwz r10, 0x28(r31)
stw r8, 0x28(r31)
andc r8, r8, r10 # rising edges; never consume or replace native input
bl _boatInputs
cmpwi r9, 0
beq _updateMap
andis. r0, r8, 4 # D-pad left
beq _checkZoom
lwz r0, 0x10(r31)
xori r0, r0, 1 # left toggles on islands too
stw r0, 0x10(r31)
b _updateMap
_checkZoom:
andis. r0, r8, 8 # D-pad right
beq _updateMap
lwz r0, 0x10(r31)
cmpwi r0, 0
beq _updateMap # right only resizes an open map
_zoomVisibleMap:
lwz r3, 4(r31)
lwz r0, 0x144(r3)
cmpwi r0, 1
bne _checkZoomSmall
li r4, 9
bl _playOwnedZoom # no menu focus or selection writes
b _updateMap
_checkZoomSmall:
cmpwi r0, 3
bne _updateMap
li r4, 8
bl _playOwnedZoom

_updateMap:
# The nested layout normally receives these calls through its GamePad root.
# Drive its own animation controllers as well when that tab is inactive.
lwz r3, 4(r31)
lwz r3, 0x44(r3)
lwz r3, 4(r3)
bl 0x026FB178
lwz r3, 4(r31)
lwz r3, 0x44(r3)
lwz r3, 4(r3)
bl 0x026FB300
lwz r3, 4(r31)
bl _ownedMapUpdate # project markers AFTER this frame's native zoom
lwz r11, 0x18(r31)
addi r11, r11, 1
stw r11, 0x18(r31)
lwz r3, 4(r31)
lwz r7, 0x90(r3) # N_StandardPos_00, complete local pane
lwz r0, 8(r31)
cmpw r0, r7
beq _position

# Find this HUD's root from its layout wrapper, then transfer the intrusive node.
lwz r8, 0x44(r30)
lwz r8, 4(r8)
lwz r8, 0x0C(r8)
lwz r9, 0x0C(r7)
stw r9, 0x0C(r31)
lwz r10, 0(r7)
lwz r11, 4(r7)
stw r10, 0(r11)
stw r11, 4(r10)
lwz r11, 0x10(r9)
addi r11, r11, -1
stw r11, 0x10(r9)
addi r9, r8, 0x14
lwz r10, 4(r9)
stw r7, 0(r10)
stw r10, 4(r7)
stw r9, 0(r7)
stw r7, 4(r9)
stw r8, 0x0C(r7)
lwz r11, 0x10(r8)
addi r11, r11, 1
stw r11, 0x10(r8)
stw r7, 8(r31)

_position:
bl _installIslandClip
lwz r0, 0x20(r31)
stw r0, 0x1C(r7)
lwz r0, 0x24(r31)
stw r0, 0x20(r7)
li r0, 0
stw r0, 0x24(r7)
lwz r0, 0x80(r31)
stw r0, 0x34(r7)
stw r0, 0x38(r7)
lwz r3, 4(r31)
lwz r8, 0x144(r3)
cmpwi r8, 2
beq _largePosition
cmpwi r8, 3
bne _visibility
_largePosition:
# The same native clip scales the plan and N_MapBig in both directions.
# Follow its progress instead of snapping to the final root pose immediately.
# Interpolate the EFFECTIVE size, then divide out the animated child scale.
# Since both endpoint poses have the same lower-left corner, interpolating
# their centers by this same progress fixes that corner throughout the zoom.
lwz r8, 0x94(r3) # private N_MapBig_00, animated with P_MapBase_00 in states 2/3
lfs f0, 0x34(r8)
lfs f6, 0x78(r31) # zero
fcmpu cr0, f0, f6
ble _visibility # retain compact fallback if the native scale is not initialized
lfs f1, 0x84(r31)
fsubs f2, f0, f1
lfs f3, 0x88(r31)
fdivs f2, f2, f3 # native eased zoom progress
fcmpu cr0, f2, f6
bge _zoomProgressPositive
fmr f2, f6
_zoomProgressPositive:
fcmpu cr0, f2, f1
ble _zoomProgressClamped
fmr f2, f1
_zoomProgressClamped:
lfs f3, 0x80(r31) # compact effective scale
lfs f4, 0x38(r31)
lfs f5, 0x8C(r31)
fmuls f4, f4, f5 # final large effective scale
fsubs f4, f4, f3
fmuls f4, f4, f2
fadds f4, f4, f3
fdivs f4, f4, f0
stfs f4, 0x34(r7)
stfs f4, 0x38(r7)
lfs f3, 0x20(r31)
lfs f4, 0x30(r31)
fsubs f4, f4, f3
fmuls f4, f4, f2
fadds f4, f4, f3
stfs f4, 0x1C(r7)
lfs f3, 0x24(r31)
lfs f4, 0x34(r31)
fsubs f4, f4, f3
fmuls f4, f4, f2
fadds f4, f4, f3
stfs f4, 0x20(r7)
_visibility:
bl _prepareIslandPresentation
bl _islandFamilySize
bl _sizeIslandMarkers
bl _cleanOwnedPane
mr r3, r7
bl _hideMapBorders
lwz r7, 8(r31)
bl _coverageSlideMap
lbz r0, 0x44(r7)
ori r0, r0, 0x13 # visible + transform dirty + propagate alpha to descendants
lwz r9, 0x1C(r31) # apply opacity once at the map root, preserve native fades below
bl _mapHudFadeAlpha
stb r9, 0x45(r7)
lwz r12, 0x10(r31)
lwz r11, 0x60(r31)
or r12, r12, r11 # keep drawing until the user-close animation finishes
lwz r10, 0x2C(r31)
or r11, r11, r10 # permission OR a still-running close slide
and r12, r12, r11
cmpwi r12, 0
bne _setFlags
rlwinm r0, r0, 0, 0, 30
_setFlags:
stb r0, 0x44(r7)
bl _refreshMapMatrices
b _tickDone
_invalidate:
li r0, 0
stw r0, 4(r31)
stw r0, 8(r31)
_tickDone:
bl _dungeonTick
bl _resolveMapHudPanes
bl _updateMapActivity
bl _updateMapHints
bl _boatPresent
bl _updateMapFrame
bl _updateWindArrow
bl _boatHideLocalArt
bl _rememberMapPresentation
bl _floorScrollHudFinal
bl _airFloorFinish
lwz r0, 0x24(r1)
lwz r30, 0x18(r1)
lwz r31, 0x1C(r1)
mtlr r0
addi r1, r1, 0x20
blr

# The main HUD already calculated its matrices before this late update. Update
# our subtree with the native TV DrawInfo after setting position and visibility.
# Calculate invisible panes too: reopening must never draw a stale cached pose.
_refreshMapMatrices:
mflr r0
stwu r1, -0x28(r1)
stw r0, 0x2C(r1)
lwz r4, 0x44(r30)
addi r4, r4, 0x0C # native HUD DrawInfo
addi r3, r1, 8 # 0x18-byte native matrix-calculation context
bl 0x02877C18
li r0, 1
stb r0, 0x1D(r1) # context+0x15: calculate invisible panes
lwz r3, 8(r31)
addi r4, r1, 8
li r5, 1 # force this subtree's transform refresh
lwz r12, 8(r3)
lwz r12, 0x84(r12)
mtctr r12
bctrl
lwz r0, 0x2C(r1)
mtlr r0
addi r1, r1, 0x28
blr

# Remove menu decoration only from our private pane, after native animations.
# Labels, balloon and parchment bases are direct children; art/markers stay intact.
_cleanOwnedPane:
lwz r6, 0x14(r7)
lwz r8, 0x10(r7)
cmplwi r8, 64
bgtlr
_cleanPaneLoop:
cmpwi r8, 0
beqlr
lwz r0, 0x80(r6)
lis r9, 0x575F
ori r9, r9, 0x4D61 # W_Ma: W_MapBalloon_00
cmpw r0, r9
beq _hideDecoration
lis r9, 0x545F
ori r9, r9, 0x4465 # T_De: T_Deco_00 / T_Deco_01
cmpw r0, r9
beq _hideDecoration
# Our shared rounded backdrop replaces both native parchment base pictures.
lis r9, 0x505F
ori r9, r9, 0x4D61 # P_Ma
cmpw r0, r9
bne _checkZoomDecoration
lwz r10, 0x84(r6)
lis r9, 0x7042
ori r9, r9, 0x6173 # pBas: P_MapBase_00 / P_MapBase_01
cmpw r10, r9
beq _hideDecoration
_checkZoomDecoration:
# Suppress the separate focus backdrop on this HUD-owned instance at all sizes.
lis r9, 0x505F
ori r9, r9, 0x5A6F # P_Zo: P_ZoomMask_00
cmpw r0, r9
bne _nextDecoration
_hideDecoration:
lbz r0, 0x44(r6)
rlwinm r0, r0, 0, 0, 30
stb r0, 0x44(r6)
_nextDecoration:
lwz r6, 0(r6)
addi r8, r8, -1
b _cleanPaneLoop

# Hide dotted outlines throughout the PRIVATE map tree, after native animations.
# P_DotLine_* surrounds the compact map; P_DecoLine_* surrounds the enlarged one.
# Keep all other pictures, their local opacity and the original menu tree intact.
_hideMapBorders:
mflr r0
stwu r1, -0x18(r1)
stw r0, 0x1C(r1)
stw r30, 0x10(r1)
stw r31, 0x14(r1)
lwz r6, 0x80(r3)
lis r8, 0x505F
ori r8, r8, 0x446F # P_Do
cmpw r6, r8
bne _checkLargeBorder
lwz r6, 0x84(r3)
lis r8, 0x744C
ori r8, r8, 0x696E # tLin
cmpw r6, r8
beq _hideBorder
b _borderChildren
_checkLargeBorder:
lis r8, 0x505F
ori r8, r8, 0x4465 # P_De
cmpw r6, r8
bne _borderChildren
lwz r6, 0x84(r3)
lis r8, 0x636F
ori r8, r8, 0x4C69 # coLi
cmpw r6, r8
bne _borderChildren
_hideBorder:
lbz r0, 0x44(r3)
rlwinm r0, r0, 0, 0, 30
stb r0, 0x44(r3)
_borderChildren:
lwz r30, 0x14(r3)
lwz r31, 0x10(r3)
cmplwi r31, 64
bgt _borderDone
_borderChildLoop:
cmpwi r31, 0
beq _borderDone
mr r3, r30
bl _hideMapBorders
lwz r30, 0(r30)
addi r31, r31, -1
b _borderChildLoop
_borderDone:
lwz r0, 0x1C(r1)
lwz r30, 0x10(r1)
lwz r31, 0x14(r1)
mtlr r0
addi r1, r1, 0x18
blr

# 200 ms on the emulated Espresso timer (62,156,250 Hz), independent of FPS.
# E(t)=(2^(4*t)-1)/15 in BOTH directions: slow start, accelerating finish.
# 128 table intervals (<2 ms each); elapsed subtraction handles timer wrap.
# Native HUD restrictions still hide immediately. Discovered local-plan
# boundary exits share the user-close animation; reversal keeps its position.
# Leaf: r7 is the attached pane; r31 is pack state; volatile registers only.
_slideMap:
lwz r8, 0x10(r31)
lwz r0, 0x4C(r31)
cmpwi r0, 2
bne _slideRequestedReady
li r8, 0 # outside local coverage: close without changing the preference
_slideRequestedReady:
lfs f3, 0x78(r31) # destination when opening = 0
cmpwi r8, 0
bne _slideDestinationReady
lfs f3, 0x70(r31)
lwz r6, 4(r31)
lwz r0, 0x144(r6)
cmplwi r0, 2
blt _slideDestinationReady
lfs f3, 0x74(r31)
_slideDestinationReady:
lwz r0, 0x4C(r31)
cmpwi r0, 2
bne _slideInitialCheck
lbz r0, 0x44(r7)
andi. r0, r0, 1
beq _slideSnap # never resurrect a hidden map just to animate its exit
_slideInitialCheck:
lwz r0, 0x54(r31)
cmpwi r0, 0
beq _slideSnap
lwz r0, 0x2C(r31)
cmpwi r0, 0
bne _slideContextReady
lwz r0, 0x4C(r31)
cmpwi r0, 2
bne _slideSnap
_slideContextReady:
.int 0x7CCC42E6 # mftb r6, Espresso time-base lower word
lwz r0, 0x58(r31)
cmpw r8, r0
beq _slideAdvance
stw r8, 0x58(r31)
stw r6, 0x5C(r31)
lfs f0, 0x64(r31)
stfs f0, 0x68(r31)
stfs f3, 0x6C(r31)
li r0, 1
stw r0, 0x60(r31)
_slideAdvance:
lwz r0, 0x60(r31)
cmpwi r0, 0
beq _slideApply
lwz r9, 0x5C(r31)
subf r9, r9, r6
lwz r0, 0x58(r31)
cmpwi r0, 0
beq _slideExitTiming
lis r10, 0x00BD
ori r10, r10, 0xAF92 # entrance: original 200 ms
lis r11, 1
ori r11, r11, 0x7B5F
b _slideTimingReady
_slideExitTiming:
lis r10, 0x00ED
ori r10, r10, 0x1B77 # exit: 15,539,063 ticks = 250 ms
lis r11, 1
ori r11, r11, 0xDA37
_slideTimingReady:
cmplw r9, r10
bge _slideFinish
divwu r9, r9, r11
slwi r9, r9, 2
lis r10, _slideEase@ha
addi r10, r10, _slideEase@l
cmpwi r0, 0
bne _slideSampleReady
lis r10, _mapExitEase@ha
addi r10, r10, _mapExitEase@l
_slideSampleReady:
lfsx f2, r10, r9
lfs f0, 0x68(r31)
lfs f1, 0x6C(r31)
fsubs f1, f1, f0
fmuls f1, f1, f2
fadds f0, f0, f1
stfs f0, 0x64(r31)
b _slideApply
_slideFinish:
li r0, 0
stw r0, 0x60(r31)
lfs f0, 0x6C(r31)
stfs f0, 0x64(r31)
b _slideApply
_slideSnap:
li r0, 1
stw r0, 0x54(r31)
stw r8, 0x58(r31)
li r0, 0
stw r0, 0x60(r31)
stfs f3, 0x64(r31)
stfs f3, 0x68(r31)
stfs f3, 0x6C(r31)
_slideApply:
lfs f0, 0x1C(r7)
lfs f1, 0x64(r31)
fadds f0, f0, f1
stfs f0, 0x1C(r7)
blr

# Added pictures are children of the existing ShortcutState pane, so native
# HUD positioning and opacity apply. Identify them by name, never heap address.
# This leaf uses volatile registers only; r30/r31 are the HUD and pack state.
_updateMapHints:
li r9, 0
li r7, 0 # small zoom by default
lwz r8, 4(r31)
cmpwi r8, 0
beq _findHintPanes
lwz r9, 0x2C(r31)
lwz r0, 0x144(r8)
cmpwi r0, 2 # entering large zoom
beq _largeZoomHint
cmpwi r0, 3 # stable large zoom
bne _findHintPanes
_largeZoomHint:
li r7, 1
_findHintPanes:
lwz r4, 0x10(r31)
lis r8, _dungeonState@ha
addi r8, r8, _dungeonState@l
lwz r0, 0x10(r8)
mr r5, r0 # compass hint only in an eligible dungeon, never on an island
cmpwi r0, 0
beq _islandHintContext
li r9, 1
lwz r4, 0x14(r8) # dungeon visibility, independent of island choice
lwz r7, 0x18(r8)
_islandHintContext:
lwz r0, 0x7C(r31)
cmpwi r0, 0
beq _boatHintsDone
li r9, 0
li r5, 0
li r7, 0 # no foot frame-size shortcut aboard
li r4, 0 # left/right/down foot hints never overlap native boat tools
_boatHintsDone:
lwz r8, 0x4C(r30)
lwz r8, 0x30(r8) # native Shortcut object, child 12 in EU v0
lwz r8, 0x44(r8)
lwz r8, 4(r8)
lwz r8, 0x0C(r8) # L_Shortcut_00
lwz r8, 0x14(r8) # N_Shortcut_00
lwz r8, 0x14(r8) # N_All_00
lwz r8, 0x14(r8) # N_ShortcutInOut_00
lwz r8, 0x14(r8) # N_ShortcutState_00
lwz r6, 0x14(r8)
lwz r10, 0x10(r8)
cmplwi r10, 18 # bounded shortcut tree with one disabled foot hint
bgtlr # unexpected resource tree: leave the hints hidden
_hintLoop:
cmpwi r10, 0
beqlr
lwz r0, 0x80(r6)
lis r11, 0x4D48
ori r11, r11, 0x695F # MHi_: hide picture
cmpw r0, r11
bne _checkZoomHint
mr r12, r9 # left remains available to reopen an eligible map
b _setHintVisible
_checkZoomHint:
lis r11, 0x4D5A
ori r11, r11, 0x6F5F # MZo_: blue plus, enlarge small map
cmpw r0, r11
bne _checkReduceHint
xori r12, r7, 1
and r12, r12, r9
and r12, r12, r4
b _setHintVisible
_checkReduceHint:
lis r11, 0x4D5A
ori r11, r11, 0x6D5F # MZm_: red minus, reduce large map
cmpw r0, r11
bne _checkCompassHint
and r12, r7, r9
and r12, r12, r4
b _setHintVisible
_checkCompassHint:
lis r11, 0x4D43
ori r11, r11, 0x705F # MCp_: native compass group, including its shadow
cmpw r0, r11
bne _checkBoatMapHint
and r12, r5, r4 # dungeon rotation hint only while open
lis r11, _resourceState@ha
addi r11, r11, _resourceState@l
lwz r11, 8(r11)
and r12, r12, r11
b _setHintVisible
_checkBoatMapHint:
lis r11, 0x4D42
ori r11, r11, 0x6F5F # MBo_: map/loupe and shadow on D-pad down
cmpw r0, r11
bne _checkUnknownBoatHint
b _boatDungeonMapHint
_boatMapHintMarine:
lwz r0, 0x40(r31)
cmpwi r0, 1
bne _setHintVisible # no usable private map object yet
lwz r0, 4(r31)
cmpwi r0, 0
beq _setHintVisible
lis r11, _boatState@ha
addi r11, r11, _boatState@l
lwz r12, 0x7C(r31)
lwz r0, 8(r11)
and r12, r12, r0 # currently aboard, normal sea HUD eligible
lwz r0, 0x6C(r11)
and r12, r12, r0 # actual discovery, never the temporary closing permission
lwz r0, 0xB8(r11)
and r12, r12, r0 # Link is inside the current local map
# Deliberately independent of selected boat mode: available in compass mode too.
b _setHintVisible
_checkUnknownBoatHint:
lis r11, 0x4D55
ori r11, r11, 0x6E5F # MUn_: faded map and red question mark
cmpw r0, r11
bne _checkUnknownFootHint
lwz r12, 0x7C(r31) # bottom question-mark hint while aboard
b _unknownHintContext
_checkUnknownFootHint:
lis r11, 0x4D46
ori r11, r11, 0x745F # MFt_: grey left icon with red question mark; no right icon
cmpw r0, r11
bne _nextHint
# The native Shortcut State animation fades this parent from 255 to 60
# when disabled (e.g. swimming). Use its LOCAL alpha, not global cinematic
# visibility, to desaturate the foot glyph while retaining inherited alpha.
# MUn_ (aboard) never takes this path. Soften the overlapping black outline,
# but let the fill inherit the native HUD fade exactly once, like item icons.
lwz r12, 0x10(r6)
cmpwi r12, 0
beq _footQuestionTintDone # shadow picture has no text children
cmplwi r12, 9
bgt _footQuestionTintDone
lwz r11, 0x0C(r6)
lbz r11, 0x45(r11)
addi r11, r11, -60
cmpwi r11, 0
bge _footQuestionTintMix
li r11, 0
_footQuestionTintMix:
# Muted red (176,80,80) -> authored red (240,24,24). Pure grey disappears
# into the grey card artwork; the disabled item icons also retain some hue.
li r0, 195
mulli r12, r11, 64
divwu r12, r12, r0
addi r12, r12, 176
slwi r3, r12, 24
mulli r12, r11, 56
divwu r12, r12, r0
subfic r12, r12, 80
slwi r0, r12, 16
or r3, r3, r0
slwi r0, r12, 8
or r3, r3, r0
ori r3, r3, 0xFF
lwz r11, 0x14(r6)
lwz r12, 0x10(r6)
_footQuestionTintLoop:
lwz r0, 0x80(r11)
lis r8, 0x4D46
ori r8, r8, 0x745F # MFt_
cmpw r0, r8
bne _footQuestionTintNext
# The loader does not initialize bytes beyond the name terminator. Compare
# only Q and the digit, not the word containing arbitrary trailing padding.
lhz r0, 0x84(r11)
li r8, 0x5138 # Q8, red fill only; Q0..7 are the black outline
cmpw r0, r8
beq _footQuestionFillAlpha
li r8, 0x5130
cmplw r0, r8
blt _footQuestionTintNext
li r8, 0x5137
cmplw r0, r8
bgt _footQuestionTintNext
lwz r8, 0x0C(r6)
lbz r8, 0x45(r8)
addi r8, r8, -60
cmpwi r8, 0
bge _footQuestionOutlineAlpha
li r8, 0
_footQuestionOutlineAlpha:
# Disabled: 64/255 per outline layer, before native HUD attenuation.
# Enabled: full opacity, preserving the current black contour at radius 2.
mulli r8, r8, 191
li r0, 195
divwu r8, r8, r0
addi r8, r8, 64
stb r8, 0x45(r11)
b _footQuestionTintNext
_footQuestionFillAlpha:
# The native parent already supplies the disabled-state opacity (60/255).
li r8, 255
stb r8, 0x45(r11)
lwz r0, 0xAC(r11)
cmpw r0, r3
beq _footQuestionTintDone
stw r3, 0xAC(r11)
stw r3, 0xB0(r11)
lbz r0, 0xF4(r11)
ori r0, r0, 0x20 # native TextBox color-dirty flag
stb r0, 0xF4(r11)
b _footQuestionTintDone
_footQuestionTintNext:
lwz r11, 0(r11)
addi r12, r12, -1
cmpwi r12, 0
bne _footQuestionTintLoop
_footQuestionTintDone:
lwz r12, 0x7C(r31)
xori r12, r12, 1 # on foot only; actual sea-stage discovery gate follows
_unknownHintContext:
lis r11, _boatState@ha
addi r11, r11, _boatState@l
lwz r0, 8(r11)
and r12, r12, r0 # normal island/sea HUD, never interiors or dungeons
lis r11, _boatUnknownSector@ha
lwz r0, _boatUnknownSector@l(r11)
and r12, r12, r0 # undiscovered AND inside the real current local plan
lis r11, _resourceState@ha
addi r11, r11, _resourceState@l
lwz r0, 8(r11)
and r12, r12, r0 # custom shortcut reconstruction must have succeeded
_setHintVisible:
lbz r0, 0x44(r6)
rlwinm r0, r0, 0, 0, 30
or r0, r0, r12
stb r0, 0x44(r6)
_nextHint:
lwz r6, 0(r6)
addi r10, r10, -1
b _hintLoop

# Restore ownership before either layout is destroyed (load/title transitions).
_detachMap:
lis r12, _mapState@ha
addi r12, r12, _mapState@l
lwz r7, 8(r12)
cmpwi r7, 0
beq _clearState
lwz r8, 0x0C(r12)
cmpwi r7, 0
beq _clearState
cmpwi r8, 0
beq _clearState
lwz r9, 0x0C(r7)
cmpwi r9, 0
beq _clearState
lwz r10, 0(r7)
lwz r11, 4(r7)
cmpwi r10, 0
beq _clearState
cmpwi r11, 0
beq _clearState
lwz r0, 4(r10)
cmpw r0, r7
bne _clearState
lwz r0, 0(r11)
cmpw r0, r7
bne _clearState
lwz r0, 0x10(r9)
cmpwi r0, 0
beq _clearState
addi r6, r8, 0x14
lwz r5, 0(r6)
cmpwi r5, 0
beq _clearState
lwz r0, 4(r5)
cmpw r0, r6
bne _clearState
lwz r5, 4(r6)
cmpwi r5, 0
beq _clearState
lwz r0, 0(r5)
cmpw r0, r6
bne _clearState
stw r10, 0(r11)
stw r11, 4(r10)
lwz r11, 0x10(r9)
addi r11, r11, -1
stw r11, 0x10(r9)
addi r9, r8, 0x14
lwz r10, 4(r9)
stw r7, 0(r10)
stw r10, 4(r7)
stw r9, 0(r7)
stw r7, 4(r9)
stw r8, 0x0C(r7)
lwz r11, 0x10(r8)
addi r11, r11, 1
stw r11, 0x10(r8)
li r0, 0
stw r0, 0x1C(r7)
stw r0, 0x24(r7)
lis r0, 0x42F0 # original y=120
stw r0, 0x20(r7)
lis r0, 0x3F80
stw r0, 0x34(r7)
stw r0, 0x38(r7)
lbz r0, 0x44(r7)
ori r0, r0, 0x11
stb r0, 0x44(r7)
_clearState:
li r0, 0
stw r0, 4(r12)
stw r0, 8(r12)
stw r0, 0x0C(r12)
stw r0, 0x54(r12)
stw r0, 0x60(r12)
stw r0, 0x90(r12)
blr

# Detach and destroy the private layout before its source resources go away.
_releaseOwnedMap:
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
lis r12, _mapState@ha
addi r12, r12, _mapState@l
lwz r3, 4(r12)
stw r3, 8(r1)
bl _detachMap
lis r12, _mapState@ha
addi r12, r12, _mapState@l
li r0, 0
stw r0, 0x3C(r12)
stw r0, 0x40(r12)
stw r0, 0x2C(r12)
stw r0, 0x4C(r12)
stw r0, 0x50(r12)
lwz r3, 8(r1)
cmpwi r3, 0
beq _releaseDone
li r4, 1
bl _nativeMapDestructor
_releaseDone:
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
blr

_mapDestructor:
lis r12, _mapState@ha
addi r12, r12, _mapState@l
lwz r11, 0x3C(r12)
cmpw r3, r11
bne _nativeMapDestructor
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
stw r3, 8(r1)
stw r4, 0x0C(r1)
bl _releaseOwnedMap
lwz r3, 8(r1)
lwz r4, 0x0C(r1)
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
_nativeMapDestructor:
mflr r0
b 0x026375FC+4

_hudDestructor:
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
stw r3, 8(r1)
stw r4, 0x0C(r1)
bl _releaseBoat
bl _releaseOwnedMap
bl _releaseDungeon
lwz r3, 8(r1)
lwz r4, 0x0C(r1)
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
b 0x02676190+4

# Build a fresh standalone layout after the source atlas has initialized.
_ensureOwnedMap:
lis r12, _resourceState@ha
addi r12, r12, _resourceState@l
lwz r0, 4(r12)
cmpwi r0, 1
bnelr
lwz r0, 0x40(r31)
cmpwi r0, 0
bnelr
lwz r8, 0x3C(r31)
cmpwi r8, 0
beqlr
lwz r8, 0x164(r8)
cmpwi r8, 0
beqlr
# Some inactive atlas instances contain placeholder records (id=-1).
# Wait for the captured atlas geometry to have actually been populated.
lwz r8, 0(r8)
cmpwi r8, 0
beqlr
lwz r8, 0(r8)
cmpwi r8, 0
bnelr
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
li r0, -1
stw r0, 0x40(r31)
stw r0, 0x44(r31)
stw r0, 0x48(r31)
lis r4, 0x1019
lwz r4, -0x3BFC(r4)
lwz r4, 0x10(r4)
li r3, 0x168
li r5, 4
bl 0x0273B90C
cmpwi r3, 0
beq _createDone
bl 0x02637DE4
stw r3, 4(r31)
li r4, 0
li r5, 0
li r6, 0
bl 0x026386E4
cmpwi r3, 0
beq _createDone
lwz r3, 4(r31)
lis r8, _worldContext@ha
addi r8, r8, _worldContext@l
stw r8, 0x164(r3)
lis r9, _worldRecord@ha
addi r9, r9, _worldRecord@l
stw r9, 0x118(r8)
stw r9, 0x11C(r8)
li r0, 1
stw r0, 0x40(r31)
li r4, 8
bl _playOwnedZoom
_createDone:
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
blr

# Select geometry by the REAL current island (native world feed +0x3E).
# The menu's selected-record fields +0x118/+0x11C are never read or written.
_selectWorldMap:
mflr r0
stwu r1, -0x20(r1)
stw r0, 0x24(r1)
stw r28, 0x18(r1)
stw r29, 0x1C(r1)
li r0, 0
stw r0, 0x4C(r31)
lis r8, 0x1020
lwz r8, -0x7CA4(r8)
lwz r8, 0x218(r8)
lbz r29, 0x3E(r8)
cmplwi r29, 49
bge _worldInvalid
lwz r9, 0x3C(r31)
cmpwi r9, 0
beq _worldInvalid
lwz r9, 0x164(r9)
cmpwi r9, 0
beq _worldInvalid
slwi r10, r29, 2
lwzx r28, r9, r10
cmpwi r28, 0
beq _worldInvalid
lwz r0, 0(r28)
cmpw r0, r29
bne _worldInvalid
lhz r0, 4(r28)
lhz r10, 0x3C(r8)
cmpw r0, r10
bne _worldInvalid
lis r3, 0x1020
lwz r3, -0x7B0C(r3)
addi r3, r3, 0xE4
mr r4, r29
bl 0x025B8528 # same fish-chart save query as native atlas population
cmpwi r3, 0
bne _unknownCoverageDone
bl _unknownLocalCoverage
lis r12, _boatUnknownSector@ha
stw r3, _boatUnknownSector@l(r12)
li r3, 0 # preserve the native undiscovered result for map selection
_unknownCoverageDone:
lwz r0, 0x7C(r31)
cmpwi r0, 0
beq _boatWorldDiscoveryReady
cmpwi r3, 0
beq _worldInvalid
_boatWorldDiscoveryReady:
lwz r0, 0x44(r31)
cmpw r0, r29
bne _refreshWorldRecord
lwz r0, 0x48(r31)
cmpw r0, r3
beq _worldReady
_refreshWorldRecord:
stw r29, 0x44(r31)
stw r3, 0x48(r31)
lis r9, _worldRecord@ha
addi r9, r9, _worldRecord@l
li r10, 0
_copyGeometry:
lwzx r11, r28, r10
stwx r11, r9, r10
addi r10, r10, 4
cmpwi r10, 0x10
blt _copyGeometry
stb r3, 0x97(r9) # owned POD only; never write the save/native menu record
lwz r3, 4(r31)
mr r4, r9
bl 0x02637A5C # native island texture and geometry
_worldReady:
li r0, 1
stw r0, 0x4C(r31)
lwz r0, 0x48(r31)
cmpwi r0, 0
bne _worldSelectionDone
_worldInvalid:
li r0, 0
stw r0, 0x2C(r31) # fail closed: no stale or undiscovered island picture
_worldSelectionDone:
# Apply the same native local-plan bounds on foot and while swimming.
# Boat presentation keeps its existing coverage/treasure/exit policy.
lwz r0, 0x7C(r31)
cmpwi r0, 0
bne _worldSelectionReturn
lwz r0, 0x2C(r31)
cmpwi r0, 0
beq _worldSelectionReturn
bl _boatLocalCoverage
stw r3, 0x2C(r31)
li r0, 2
subf r0, r3, r0
stw r0, 0x4C(r31) # 1 inside; 2 valid discovered plan outside its bounds
_worldSelectionReturn:
lwz r0, 0x24(r1)
lwz r28, 0x18(r1)
lwz r29, 0x1C(r1)
mtlr r0
addi r1, r1, 0x20
blr

_playOwnedZoom:
mflr r0
stwu r1, -0x18(r1)
stw r0, 0x1C(r1)
stw r3, 8(r1)
lis r12, _mapState@ha
addi r12, r12, _mapState@l
li r0, 0
stw r0, 0x90(r12)
li r6, 0 # normal playback, not initial compact-pose setup
lis r11, 0x100F
lfs f1, -0x6A90(r11) # native animation speed 1
cmpwi r4, 8
bne _zoomAnimatedState
lwz r0, 0x144(r3)
cmpwi r0, 3
beq _zoomReverse
# First creation: bind the enlarge clip at its compact endpoint, no unfold.
li r6, 1
li r0, 1
b _zoomState
_zoomReverse:
li r0, 1
stw r0, 0x90(r12)
fneg f1, f1 # native playback starts at the last frame for a negative speed
_zoomAnimatedState:
li r0, 2
_zoomState:
stw r0, 0x144(r3)
stw r6, 0x0C(r1)
# Local geometry offsets; no atlas cursor or input focus.
li r0, 0
stw r0, 0xDC(r3)
stw r0, 0xE0(r3)
lwz r3, 0x44(r3)
lwz r3, 0xD4(r3)
li r4, 9 # use ONLY the enlarge clip, forwards or backwards, on our instance
li r5, 5
cmpwi r6, 0
bne _zoomInitialPose
bl 0x020053E4
b _zoomPlaybackDone
_zoomInitialPose:
bl 0x02005674 # bind animation and stop at frame zero
_zoomPlaybackDone:
lwz r0, 0x1C(r1)
mtlr r0
addi r1, r1, 0x18
blr

_ownedMapUpdate:
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
stw r30, 0x0C(r1)
mr r30, r3
lis r12, _mapState@ha
addi r12, r12, _mapState@l
lwz r0, 0x90(r12)
cmpwi r0, 0
beq _finishForwardZoom
# Keep state 2 while reversing: its projection/markers follow the same plan.
# Native state 0 would run the unrelated small-thumbnail unfolding behavior.
lwz r3, 0x44(r30)
lwz r3, 0xD4(r3)
li r4, 9
bl 0x02005840 # native animation completion, valid for negative speed too
cmpwi r3, 0
beq _updateOwnedProjection
lis r12, _mapState@ha
addi r12, r12, _mapState@l
li r0, 0
stw r0, 0x90(r12)
li r0, 1
stw r0, 0x144(r30)
b _updateOwnedProjection
_finishForwardZoom:
mr r3, r30
bl 0x026387A4 # finish zoom transitions
_updateOwnedProjection:
lis r12, _boatState@ha
addi r12, r12, _boatState@l
lwz r0, 0xBC(r12)
cmpwi r0, 0
bne _boatFrozenProjection
mr r3, r30
bl 0x02638F80 # native local-map offset/projection
mr r3, r30
bl 0x026397C8 # Link position and orientation
mr r3, r30
bl 0x02639CF0 # boat marker on the current island, not navigation HUD
_boatFrozenProjection:
lwz r0, 0x14(r1)
lwz r30, 0x0C(r1)
mtlr r0
addi r1, r1, 0x10
blr

