# Dungeon component: private native layouts, no menu input or floor selection.
_dungeonState:
.int 0x444E4730 # DNG0
.int 0 # +04 private object
.int 0 # +08 native source, read only
.int 0 # +0C creation status
.int 0 # +10 context allows
.int 1 # +14 user visibility
.int 0 # +18 frame size
.int 0 # +1C native camera-follow zoom
.int 0 # +20 previous buttons
.int -1 # +24 dungeon id
.int 0 # +28 current stage word 0
.int 0 # +2C current stage word 1
.int -1 # +30 actual floor/room
.float 195.7 # +34 animated frame width
.float 195.7 # +38 target width
.float 0 # +3C horizontal slide offset
.int 0 # +40 slide timestamp
.int 0 # +44 slide active
.float 0 # +48 slide start
.float 0 # +4C slide end
.float 195.7 # +50 compact width
.float 290.048 # +54 large width
.float 0.5 # +58 half
.float -616 # +5C left margin in 1280x720 canvas
.float -336 # +60 bottom margin
.float 0 # +64 zero
.float 1 # +68 one
.float 500 # +6C native frame width
.int 255 # +70 floor root: native HUD fade only; actor markers retain 179
.int 0 # +74 tick count
.int 0 # +78 draw count
.int 0 # +7C context initialized
.int 0 # +80 source load r4
.int 0 # +84 source load r5
.int 0 # +88 source load r6
.float 195.7 # +8C size start
.int 0 # +90 size timestamp
.int 0 # +94 size active
.int 0 # +98 last visibility
.int 0 # +9C actual floor available
.float 0 # +A0 screen center X
.float 0 # +A4 screen center Y
.int 0 # +A8 presentation transform currently applied
.float 543.478260870 # +AC padded content divisor; 4% per edge

_captureDungeonInit:
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
lis r12, _dungeonState@ha
addi r12, r12, _dungeonState@l
stw r3, 8(r12)
stw r4, 0x80(r12)
stw r5, 0x84(r12)
stw r6, 0x88(r12)
bl 0x0265C9AC
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
blr
0x0268B8A0 = bl _captureDungeonInit

# Standalone build shares immutable archive only. Every pane is newly allocated.
_dungeonBuild:
lis r12, _dungeonState@ha
addi r12, r12, _dungeonState@l
lwz r11, 4(r12)
cmpw r3, r11
bne _dungeonNativeBuild
lwz r11, 8(r12)
lwz r11, 0x44(r11)
lwz r11, 4(r11)
lwz r5, 0x20(r11)
_dungeonNativeBuild:
stwu r1, -0x28(r1)
b 0x0265D778
0x0265D774 = b _dungeonBuild

_dungeonTick:
lis r12, _resourceState@ha
addi r12, r12, _resourceState@l
lwz r0, 4(r12)
cmpwi r0, 1
bnelr
mflr r0
stwu r1, -0x28(r1)
stw r0, 0x2C(r1)
stmw r27, 0x14(r1)
lis r31, _dungeonState@ha
addi r31, r31, _dungeonState@l
lwz r8, 0x74(r31)
addi r8, r8, 1
stw r8, 0x74(r31)
li r0, 0
stw r0, 0x10(r31)
# Read edges even while gated, so buttons held across a transition do not fire.
lis r8, 0x101F
lwz r8, 0x50A0(r8)
lwz r8, 0x124(r8)
lwz r0, 0x20(r31)
stw r8, 0x20(r31)
andc r27, r8, r0
# Riding does not override native dungeon selection.
lbz r0, 0xA7(r30)
cmpwi r0, 0
bne _dungeonTickDone
lwz r8, 0x4C(r30)
lwz r8, 0(r8)
lwz r8, 0x44(r8)
lwz r8, 4(r8)
lwz r8, 0x0C(r8)
lwz r8, 0x14(r8)
lbz r0, 0x44(r8)
andi. r0, r0, 1
beq _dungeonTickDone
lbz r0, 0x45(r8)
cmpwi r0, 0
beq _dungeonTickDone
lis r8, 0x1020
lwz r8, -0x7CA4(r8)
lwz r29, 0x218(r8)
lwz r0, 0x60(r29)
cmpwi r0, 1
bne _dungeonTickDone
lwz r0, 0x50(r29)
cmplwi r0, 6
bge _dungeonTickDone
mr r3, r29
bl 0x02689A70
cmpwi r3, 0
bne _dungeonTickDone
# Native current-dungeon map ownership query (item bit 0, not the compass bit).
# Both the mini-map and its three shortcuts require the collected dungeon map.
mr r3, r29
bl 0x0268A580
cmpwi r3, 0
beq _dungeonTickDone
# An actual player/floor is also required; no stale plan during loading.
lwz r0, 0x0C(r31)
cmpwi r0, 1
beq _dungeonReady
cmpwi r0, 0
bne _dungeonTickDone
lwz r8, 8(r31)
cmpwi r8, 0
beq _dungeonTickDone
lwz r8, 0x44(r8)
cmpwi r8, 0
beq _dungeonTickDone
li r0, -1
stw r0, 0x0C(r31)
lis r4, 0x1019
lwz r4, -0x3BFC(r4)
lwz r4, 0x10(r4)
li r3, 0x928
li r5, 4
bl 0x0273B90C
cmpwi r3, 0
beq _dungeonTickDone
bl 0x0265B9DC
stw r3, 4(r31)
lwz r4, 0x80(r31)
lwz r5, 0x84(r31)
lwz r6, 0x88(r31)
bl 0x0265C9AC
cmpwi r3, 0
beq _dungeonTickDone
li r0, 1
stw r0, 0x0C(r31)
_dungeonReady:
lwz r28, 4(r31)
bl _dungeonRestoreNativeRoots
mr r3, r28
bl 0x0265E400 # same native live companion position/rotation refresh
mr r3, r28
bl 0x02655744
lbz r0, 0x31C(r28)
cmplwi r0, 0x7E
blt _dungeonTickDone
cmplwi r0, 0x87
bgt _dungeonTickDone
stb r0, 0x3D0(r28)
# Rebuild per-room native discovery records, never borrow GamePad records.
lhz r8, 0x31C(r28)
lwz r9, 0x30(r31)
cmpw r8, r9
bne _dungeonPrepare
lwz r8, 0x50(r29)
lwz r9, 0x24(r31)
cmpw r8, r9
bne _dungeonPrepare
lis r8, 0x1047
lwz r9, 0x41E4(r8)
lwz r10, 0x28(r31)
cmpw r9, r10
bne _dungeonPrepare
lwz r9, 0x41E8(r8)
lwz r10, 0x2C(r31)
cmpw r9, r10
beq _dungeonInputs
_dungeonPrepare:
mr r3, r28
lwz r4, 0x50(r29)
bl _floorScrollCanPrepare
stw r3, 8(r1)
lwz r0, 0x50(r29)
stw r0, 0x24(r31)
lis r8, 0x1047
lwz r0, 0x41E4(r8)
stw r0, 0x28(r31)
lwz r0, 0x41E8(r8)
stw r0, 0x2C(r31)
lhz r0, 0x31C(r28)
stw r0, 0x30(r31)
lwz r0, 8(r1)
cmpwi r0, 0
beq _dungeonOriginalFloorPrepare
mr r3, r28
bl _floorPrepareKeepPose
b _dungeonInputs
_dungeonOriginalFloorPrepare:
mr r3, r28
bl 0x0265A6A4
mr r3, r28
bl 0x0265A7A4 # native floor appear
mr r3, r28
bl 0x0265A7B4 # native marker appear
lwz r0, 0x1C(r31)
cmpwi r0, 0
beq _dungeonInputs
mr r3, r28
bl 0x0265B828
_dungeonInputs:
# HUD suppression resets the slide initializer. Settle the PREVIOUS user
# preference before processing this tick's Left edge, otherwise the first
# close/open on HUD return is mistaken for initial layout and snaps instantly.
# _dungeonAnimate preserves r27 (input edges), r28 (owned map) and r31.
bl _dungeonFamilySize
bl _dungeonBoatInputs
cmpwi r0, 0
bne _dungeonResumeReady
bl _dungeonAnimate
_dungeonResumeReady:
li r0, 1
stw r0, 0x10(r31)
andis. r0, r27, 4
beq _dungeonRight
lwz r0, 0x14(r31)
xori r0, r0, 1
stw r0, 0x14(r31)
_dungeonRight:
lwz r0, 0x14(r31)
cmpwi r0, 0
beq _dungeonLayout # hidden size/rotation commands are inactive
andis. r0, r27, 8
beq _dungeonDown
lwz r0, 0x18(r31)
xori r0, r0, 1
stw r0, 0x18(r31)
_dungeonDown:
andis. r0, r27, 2
beq _dungeonLayout
lwz r0, 0x1C(r31)
xori r0, r0, 1
stw r0, 0x1C(r31)
mr r3, r28
cmpwi r0, 0
beq _dungeonUnzoom
bl 0x0265B828
b _dungeonLayout
_dungeonUnzoom:
bl 0x0265B91C
_dungeonLayout:
# The anchor drives the plan AND all native markers. The scissor stays square.
bl _dungeonAnimate
lfs f0, 0x34(r31)
lwz r8, 0x54(r28)
lwz r9, 0x0C(r8) # N_MapArea
lwz r10, 0x0C(r9) # N_All
li r0, 0x13
stb r0, 0x44(r10)
stb r0, 0x44(r9)
li r0, 255
stb r0, 0x45(r10)
stb r0, 0x45(r9)
lfs f1, 0x64(r31)
stfs f1, 0x1C(r10)
stfs f1, 0x20(r10)
stfs f1, 0x1C(r9)
stfs f1, 0x20(r9)
lfs f2, 0x58(r31)
fmuls f2, f0, f2
lfs f3, 0x5C(r31)
fadds f3, f3, f2
lfs f5, 0x3C(r31)
fadds f3, f3, f5
lfs f4, 0x60(r31)
fadds f4, f4, f2
stfs f3, 0xA0(r31)
stfs f4, 0xA4(r31)
# Native projection and native camera zoom remain in their original 500-unit
# coordinate space. Scale their final plan and marker outputs together below.
lfs f5, 0x64(r31)
stfs f5, 0x1C(r8)
stfs f5, 0x20(r8)
lfs f5, 0x6C(r31)
stfs f5, 0x3C(r8)
stfs f5, 0x40(r8)
lwz r9, 0x50(r28)
stfs f3, 0x1C(r9)
stfs f4, 0x20(r9)
stfs f0, 0x3C(r9)
stfs f0, 0x40(r9)
li r0, 0x13
stb r0, 0x44(r8)
stb r0, 0x44(r9)
mr r3, r28
bl 0x0265C8DC # recompute anchor scale
stfs f1, 0x3AC(r28)
mr r3, r28
bl 0x02658618 # world-to-map projection
lwz r3, 0x44(r28)
lwz r3, 4(r3)
lwz r3, 0x0C(r3)
bl _dungeonMatrices
# Select a controlled sage only for this private map's presentation.
mr r3, r28
bl _sageDungeonPresent
# Apply opacity and TV matrices to independently owned native draw components.
lwz r9, 0x70(r31)
bl _mapHudFadeAlpha
stw r9, 0x0C(r1) # same native HUD fade for every private floor/marker root
addi r29, r28, 0xA0
li r27, 142 # six floors, seven actor markers, and bounded native marker arrays
_dungeonAlphaLoop:
lwz r8, 0(r29)
cmpwi r8, 0
beq _dungeonAlphaNext
lwz r8, 0x44(r8)
cmpwi r8, 0
beq _dungeonAlphaNext
lwz r8, 4(r8)
stw r8, 8(r1)
mr r3, r8
bl 0x026FB178
lwz r3, 8(r1)
bl 0x026FB300
lwz r8, 8(r1)
lwz r3, 0x0C(r8)
# One final affine transform for geometry AND markers, after all native zoom,
# panning and camera rotation. Their internal coordinate space stays unchanged.
lfs f0, 0x34(r31)
lfs f1, 0xAC(r31) # same inset for floor artwork and actor markers
fdivs f0, f0, f1
stfs f0, 0x34(r3)
stfs f0, 0x38(r3)
lfs f1, 0x1C(r3)
lfs f2, 0x20(r3)
fmuls f1, f1, f0
fmuls f2, f2, f0
lfs f3, 0xA0(r31)
lfs f4, 0xA4(r31)
fadds f1, f1, f3
fadds f2, f2, f4
stfs f1, 0x1C(r3)
stfs f2, 0x20(r3)
lwz r0, 0x0C(r1)
cmpwi r27, 136 # only the first six components are floor artwork
bgt _dungeonFloorAlphaReady
li r9, 255 # final shared opacity is applied after this frame activity tick
bl _mapHudFadeAlpha
mr r0, r9
_dungeonFloorAlphaReady:
cmpwi r27, 136
bgt _dungeonMarkerAlphaReady
lis r8, _dungeonNativeMarkerAlpha@ha
addi r8, r8, _dungeonNativeMarkerAlpha@l
lbz r9, 0x45(r3)
stbx r9, r8, r27 # capture native result BEFORE applying TV opacity
mullw r0, r0, r9
li r9, 255
divwu r0, r0, r9
_dungeonMarkerAlphaReady:
stb r0, 0x45(r3)
lbz r0, 0x44(r3)
ori r0, r0, 0x12
stb r0, 0x44(r3)
bl _dungeonMatrices
_dungeonAlphaNext:
addi r29, r29, 4
addi r27, r27, -1
cmpwi r27, 0
bne _dungeonAlphaLoop
li r0, 1
stw r0, 0xA8(r31)
# No frame/menu decoration is drawn; only native floor and marker components.
mr r3, r28
addi r4, r28, 0x3B8
bl 0x0265AAC0
_dungeonTickDone:
lwz r0, 0x10(r31)
cmpwi r0, 0
bne _dungeonTickRestore
lis r8, _floorScrollState@ha
addi r8, r8, _floorScrollState@l
li r0, 0
stw r0, 0(r8)
stw r0, 0x1C(r8)
lis r8, _airFloorState@ha
addi r8, r8, _airFloorState@l
stw r0, 0(r8)
stw r0, 0x18(r8)
stw r0, 0x1C(r8)
li r0, 0
stw r0, 0x7C(r31)
stw r0, 0x44(r31)
_dungeonTickRestore:
# Backdrop is updated after _updateMapActivity so both fades use this frame.
lmw r27, 0x14(r1)
lwz r0, 0x2C(r1)
mtlr r0
addi r1, r1, 0x28
blr

# The TV HUD draws this shared backdrop before either private map: 40% idle,
# transparent during movement/camera input, following the artwork's transition.
# Dungeons supply their presentation square; islands supply the native base's
# final matrices, including zoom and slide. The GamePad menu is never changed.
_updateDungeonBackdrop:
lis r8, _frameState@ha
addi r8, r8, _frameState@l
li r0, 0
stw r0, 8(r8)
stw r0, 12(r8)
lis r8, _hudPanes@ha
addi r8, r8, _hudPanes@l
lwz r3, 0x10(r8)
cmpwi r3, 0
beqlr
_dungeonBackdropFound:
lbz r0, 0x44(r3)
rlwinm r0, r0, 0, 0, 30
stb r0, 0x44(r3)
lwz r8, 0x10(r31)
cmpwi r8, 0
beq _islandBackdrop
lwz r8, 0x14(r31)
lwz r9, 0x44(r31)
or. r8, r8, r9
beqlr
lfs f0, 0x34(r31)
stfs f0, 0x3C(r3)
stfs f0, 0x40(r3)
lfs f0, 0xA0(r31)
stfs f0, 0x1C(r3)
lfs f0, 0xA4(r31)
stfs f0, 0x20(r3)
b _fitDungeonBackdropPixels
_islandBackdrop:
lis r8, _mapState@ha
addi r8, r8, _mapState@l
lwz r9, 0x2C(r8) # interaction eligibility stays false outside coverage
lwz r11, 0x60(r8)
or r9, r9, r11 # backdrop/frame may finish the existing close slide
cmpwi r9, 0
beqlr
lwz r8, 8(r8)
cmpwi r8, 0
beqlr
lbz r9, 0x44(r8)
andi. r9, r9, 1 # includes user visibility and the running close slide
beqlr
lwz r10, 0x10(r8)
cmplwi r10, 64
bgtlr
lwz r8, 0x14(r8)
_islandBackdropBase:
cmpwi r10, 0
beqlr
lwz r9, 0x80(r8)
lis r11, 0x505F
ori r11, r11, 0x4D61 # P_Ma
cmpw r9, r11
bne _islandBackdropNext
lwz r9, 0x84(r8)
lis r11, 0x7042
ori r11, r11, 0x6173 # pBas
cmpw r9, r11
bne _islandBackdropNext
lwz r9, 0x88(r8)
lis r11, 0x655F
ori r11, r11, 0x3030 # e_00
cmpw r9, r11
beq _islandBackdropGeometry
_islandBackdropNext:
lwz r8, 0(r8)
addi r10, r10, -1
b _islandBackdropBase
_islandBackdropGeometry:
# Invisible panes still get fresh matrices in _refreshMapMatrices.
lfs f0, 0x3C(r8)
lfs f1, 0x48(r8)
fmuls f0, f0, f1
stfs f0, 0x3C(r3)
stfs f0, 0x40(r3)
lfs f0, 0x54(r8)
stfs f0, 0x1C(r3)
lfs f0, 0x64(r8)
stfs f0, 0x20(r3)
_mapBackdropShow:
lis r8, _frameState@ha
addi r8, r8, _frameState@l
li r0, 1
stw r0, 8(r8)
stw r3, 12(r8)
lis r8, _activityState@ha
addi r8, r8, _activityState@l
lwz r9, 0x50(r8) # only the black backdrop uses this toggle
lbz r0, 0x44(r3)
ori r0, r0, 0x12
or r0, r0, r9
stb r0, 0x44(r3)
# Preserve LR: this helper previously tail-called the matrix calculation.
mflr r0
stwu r1, -0x20(r1)
stw r0, 0x24(r1)
# The background has an idle ceiling and follows the common fade ratio.
# The helper handles zero overall opacity before any division.
lis r8, _activityState@ha
addi r8, r8, _activityState@l
bl _backgroundCommonAlpha # separate idle level, same relative activity fade
bl _mapHudFadeAlpha
lwz r0, 0x24(r1)
mtlr r0
addi r1, r1, 0x20
stb r9, 0x45(r3)
b _dungeonBackdropGeometry

# Calculate hidden roots too; custom floor drawing does not use the menu tree.
# r30 remains the native TV HUD object throughout the dungeon tick.
_dungeonMatrices:
mflr r0
stwu r1, -0x30(r1)
stw r0, 0x34(r1)
stw r3, 0x28(r1)
lwz r4, 0x44(r30)
addi r4, r4, 0x0C
addi r3, r1, 8
bl 0x02877C18
li r0, 1
stb r0, 0x1D(r1)
lwz r3, 0x28(r1)
addi r4, r1, 8
li r5, 1
lwz r12, 8(r3)
lwz r12, 0x84(r12)
mtctr r12
bctrl
lwz r0, 0x34(r1)
mtlr r0
addi r1, r1, 0x30
blr

# Draw after native HUD, using its TV DrawInfo and a full TV clip context.
_dungeonHudDraw:
mflr r0
stwu r1, -0x38(r1)
stw r0, 0x3C(r1)
stmw r28, 0x28(r1)
mr r29, r4
bl 0x026F9398
lis r31, _dungeonState@ha
addi r31, r31, _dungeonState@l
lwz r8, 0x78(r31)
addi r8, r8, 1
stw r8, 0x78(r31)
lwz r0, 0x10(r31)
cmpwi r0, 0
beq _dungeonDrawDone
lwz r0, 0x14(r31)
cmpwi r0, 0
bne _dungeonDoDraw
lwz r0, 0x44(r31)
cmpwi r0, 0
beq _dungeonDrawDone
_dungeonDoDraw:
lis r28, _dungeonClipContext@ha
addi r28, r28, _dungeonClipContext@l
bl 0x02739E50
