lis r0, 0x4330
stw r0, 8(r1)
stw r3, 0x0C(r1)
lfd f0, 8(r1)
lfd f1, 0x28(r28)
fsub f0, f0, f1
frsp f0, f0
stfs f0, 0x14(r28)
stfs f0, 0x24(r28)
