bne _boatNativeTreasureBuild
mflr r0
stwu r1, -0x18(r1)
stw r0, 0x1C(r1)
stw r3, 8(r1)
stw r12, 0x0C(r1)
lwz r11, 0x64(r12)
lwz r11, 0x44(r11)
lwz r11, 4(r11)
lwz r5, 0x20(r11)
li r0, 1
stw r0, 0xA4(r12)
bl _boatNativeTreasureBuild
stw r3, 0x10(r1)
lwz r12, 0x0C(r1)
li r0, 0
stw r0, 0xA4(r12)
cmpwi r3, 0
beq _boatTreasureBuildDone
lwz r3, 8(r1)
lwz r3, 0x44(r3)
lwz r12, 0x0C(r1)
lwz r4, 0x68(r12)
bl 0x02002FE4
_boatTreasureBuildDone:
lwz r3, 0x10(r1)
lwz r0, 0x1C(r1)
mtlr r0
addi r1, r1, 0x18
blr
_boatNativeTreasureBuild:
stwu r1, -0x28(r1)
b 0x026ED458
0x026ED454 = b _boatTreasureBuild

_boatForgetTreasure:
lis r12, _boatState@ha
addi r12, r12, _boatState@l
lwz r11, 0x64(r12)
cmpw r3, r11
bne _boatTreasureDestruct
li r11, 0
stw r11, 0x64(r12)
stw r11, 0x68(r12)
_boatTreasureDestruct:
mflr r0
b 0x026EC73C
0x026EC738 = b _boatForgetTreasure

# Called after the authoritative riding query, before HUD/stage checks.
_boatBegin:
lis r12, _boatState@ha
addi r12, r12, _boatState@l
li r0, 0
stw r0, 8(r12)
stw r0, 0x6C(r12)
stw r0, 0xB8(r12)
stw r0, 0xBC(r12)
lis r11, _boatUnknownSector@ha
stw r0, _boatUnknownSector@l(r11)
lwz r9, 0x0C(r12)
cmpw r9, r3
beqlr
stw r3, 0x0C(r12)
stw r0, 4(r12)
stw r0, 0xB4(r12)
stw r0, 0x14(r12)
# Keep slide initialization/progress across boarding and disembarking.
lis r9, _boatExitState@ha
addi r9, r9, _boatExitState@l
stw r0, 0(r9)
cmpwi r3, 0
beq _boatRestoreFoot
stw r0, 0x80(r12)
lwz r9, 0x10(r31)
stw r9, 0x10(r12)
# Restore the last MARINE request, independently of foot visibility.
# Before the first marine use only, inherit the actual active foot family.
lis r10, _marinePreference@ha
addi r10, r10, _marinePreference@l
lwz r11, 0(r10)
cmpwi r11, 0
beq _boatInitialMarinePreference
lwz r9, 4(r10)
b _boatMarinePreferenceReady
_boatInitialMarinePreference:
lis r11, _dungeonState@ha
addi r11, r11, _dungeonState@l
lwz r10, 0x10(r11)
cmpwi r10, 0
beq _boatInitialSuppressedFoot
lwz r9, 0x14(r11)
b _boatMarinePreferenceReady
_boatInitialSuppressedFoot:
lis r11, _mapPresentationSnapshot@ha
addi r11, r11, _mapPresentationSnapshot@l
lwz r10, 0x30(r11)
cmpwi r10, 0
beq _boatMarinePreferenceReady
lwz r9, 0x34(r11)
_boatMarinePreferenceReady:
stw r9, 0xB4(r12)
stw r9, 4(r12)
blr
_boatRestoreFoot:
lwz r9, 0x10(r12)
stw r9, 0x10(r31)
b _boatStartExit # preserve the last drawn treasure panel for its exit only

# Return r9=0 in boat mode so left/right keep their native cannon/crane roles.
_boatInputs:
lwz r0, 0x7C(r31)
cmpwi r0, 0
beqlr
mflr r0
stwu r1, -0x30(r1)
stw r0, 0x34(r1)
stmw r27, 0x1C(r1)
mr r28, r8
lis r27, _boatState@ha
addi r27, r27, _boatState@l
stw r28, 0x58(r27)
lwz r0, 8(r27)
cmpwi r0, 0
beq _boatInputsDone
# Start only when native HUD eligibility returns, not invisibly during boarding.
bl _boatShrinkToCompact
lwz r0, 0x2C(r31)
stw r0, 0x6C(r27)
bl _boatLocalCoverage
stw r3, 0xB8(r27)
bl _boatCollectCharts
andis. r0, r28, 2 # D-pad down, VPAD/game processed mask 0x00020000
beq _boatCheckCycle
lwz r9, 0xB4(r27)
addi r0, r9, 1
cmpwi r0, 3
blt _boatNewMode
li r0, 0
_boatNewMode:
stw r0, 0xB4(r27)
cmpwi r0, 2
bne _boatCheckCycle
lwz r9, 0x1C(r27)
cmpwi r9, 0
bne _boatRequestTreasure
# Skip an empty treasure step, but never select a chart by island.
li r0, 0
stw r0, 0xB4(r27)
b _boatCheckAvailability
_boatRequestTreasure:
li r0, 1
stw r0, 0x50(r27)
_boatCheckCycle:
lwz r0, 0xB8(r27)
cmpwi r0, 0
beq _boatCheckAvailability
lwz r0, 0xB4(r27)
cmpwi r0, 2
bne _boatCheckAvailability
andi. r0, r28, 0x80 # L3: live game-processed input, not the raw VPAD mask
beq _boatCheckAvailability
lwz r9, 0x1C(r27)
cmpwi r9, 0
beq _boatCheckAvailability
lis r8, _boatChartList@ha
addi r8, r8, _boatChartList@l
lwz r10, 0x18(r27)
li r11, 0
_boatNextChart:
slwi r0, r11, 2
lwzx r0, r8, r0
addi r11, r11, 1
cmpw r0, r10
beq _boatNextFound
cmpw r11, r9
blt _boatNextChart
_boatNextFound:
cmpw r11, r9
blt _boatNextInRange
li r11, 0
_boatNextInRange:
slwi r11, r11, 2
lwzx r0, r8, r11
stw r0, 0x18(r27)
li r0, 1
stw r0, 0x50(r27)
_boatCheckAvailability:
lwz r0, 0xB4(r27)
# Remember the request before coverage/resource fallback changes presentation.
lis r8, _marinePreference@ha
addi r8, r8, _marinePreference@l
stw r0, 4(r8)
li r9, 1
stw r9, 0(r8)
stw r0, 4(r27)
lwz r9, 0xB8(r27)
cmpwi r9, 0
bne _boatTreasureAvailable
# Automatic fallback changes presentation, never the player's preference.
# A later valid plan restores local/local+treasure and the selected chart.
li r0, 0
stw r0, 4(r27)
b _boatVisibilityReady
_boatTreasureAvailable:
cmpwi r0, 2
bne _boatSetVisible
lwz r9, 0x1C(r27)
cmpwi r9, 0
bne _boatSetVisible
li r0, 1 # retain the local map if the treasure component cannot be displayed
stw r0, 4(r27)
_boatSetVisible:
lwz r0, 4(r27)
cmpwi r0, 2
bne _boatVisibilityReady
bl _boatEnsureTreasure
lwz r0, 0x5C(r27)
cmpwi r0, 0
bne _boatUnavailableComponent
lwz r0, 0x24(r27)
cmpwi r0, 0
bne _boatVisibilityReady
_boatUnavailableComponent:
li r0, 1
stw r0, 4(r27) # local map remains usable; retry the private component later
_boatVisibilityReady:
bl _boatKeepClosingPlan
lwz r0, 4(r27)
cmpwi r0, 0
beq _boatClose
stw r0, 0x14(r27)
li r9, 1
stw r9, 0x10(r31)
cmpwi r0, 2
bne _boatInputsDone
lwz r0, 0x50(r27)
cmpwi r0, 0
beq _boatInputsDone
bl _boatSyncMenu
b _boatInputsDone
_boatClose:
li r9, 0
stw r9, 0x10(r31)
_boatInputsDone:
li r9, 0
lmw r27, 0x1C(r1)
lwz r0, 0x34(r1)
mtlr r0
addi r1, r1, 0x30
blr

# Reuse the exact native Link projection and local-plan boundary predicate.
# This reads real position and our private world record, never menu selection,
# marker opacity, camera visibility, or a treasure chart's island association.
_boatLocalCoverage:
li r3, 0
lwz r0, 0x2C(r31)
cmpwi r0, 0
beqlr
lwz r0, 0x4C(r31)
cmpwi r0, 0
beqlr
mflr r0
stwu r1, -0x20(r1)
stw r0, 0x24(r1)
lwz r3, 4(r31)
addi r4, r1, 8
bl 0x02639314 # actual Link coordinates relative to the private island plan
bl 0x026394EC # same extent test used by native compact/large Link marker
lwz r0, 0x24(r1)
mtlr r0
addi r1, r1, 0x20
blr

# Scan native runtime chart records; query save flags through native read APIs.
_boatCollectCharts:
mflr r0
stwu r1, -0x30(r1)
stw r0, 0x34(r1)
stmw r24, 0x10(r1)
lis r24, 0x1020
lwz r24, -0x7CA4(r24)
lwz r24, 0x218(r24)
li r0, 0
stw r0, 0x50(r27)
bl _boatChartsChanged
cmpwi r3, 0
bne _boatRebuildCharts
lwz r29, 0x1C(r27)
b _boatChartsSelect
_boatRebuildCharts:
lis r8, _boatChartMembership@ha
addi r8, r8, _boatChartMembership@l
li r9, 16
li r0, 0
_boatClearMembership:
stw r0, 0(r8)
addi r8, r8, 4
addi r9, r9, -1
cmpwi r9, 0
bne _boatClearMembership
li r29, 0
li r26, 0
_boatChartScan:
mr r3, r24
mr r4, r26
bl 0x02688168
cmpwi r3, 0
beq _boatChartSkip
lbz r0, 3(r3)
cmplwi r0, 8
bgt _boatChartSkip
li r9, 1
slw r9, r9, r0
andi. r9, r9, 0x167 # native local salvage types 0,1,2,5,6,8
beq _boatChartSkip
mr r28, r0
lbz r9, 0(r3)
cmplwi r9, 1
blt _boatChartSkip
cmplwi r9, 49
bgt _boatChartSkip
# No player position/sector comparison: ownership and chart format only.
mr r3, r24
mr r4, r26
bl 0x0268AC74 # owned
cmpwi r3, 0
beq _boatChartSkip
mr r3, r24
mr r4, r26
bl 0x0268ACE0 # opened; never reveal an unread chart
cmpwi r3, 0
beq _boatChartSkip
cmpwi r28, 0
bne _boatChartAccept
mr r3, r24
mr r4, r26
bl 0x0268ADB8 # native Triforce decoding flag
cmpwi r3, 0
beq _boatChartSkip
_boatChartAccept:
lis r8, _boatChartMembership@ha
addi r8, r8, _boatChartMembership@l
li r0, 1
stbx r0, r8, r26
lis r8, _boatChartList@ha
addi r8, r8, _boatChartList@l
slwi r0, r29, 2
stwx r26, r8, r0
addi r29, r29, 1
_boatChartSkip:
addi r26, r26, 1
cmpwi r26, 61
blt _boatChartScan
_boatChartsDone:
stw r29, 0x1C(r27)
_boatChartsSelect:
li r26, -1
cmpwi r29, 0
beq _boatChosen
lis r8, _boatChartList@ha
addi r8, r8, _boatChartList@l
lwz r26, 0(r8)
lwz r9, 0x18(r27)
cmplwi r9, 60
bgt _boatReadMenuChoice
lis r8, _boatChartMembership@ha
addi r8, r8, _boatChartMembership@l
lbzx r0, r8, r9
cmpwi r0, 0
beq _boatReadMenuChoice
mr r26, r9 # retain last eligible choice when the menu shows a special chart
_boatReadMenuChoice:
lwz r10, 0x2C(r27)
cmpwi r10, 0
beq _boatChosen
lwz r0, 4(r10)
lwz r11, 0x60(r27)
cmpw r0, r11
bne _boatChosen
lwz r9, 0xAC(r10) # follow any readable local-format chart chosen in the menu
cmplwi r9, 60
bgt _boatChosen
lis r8, _boatChartMembership@ha
addi r8, r8, _boatChartMembership@l
lbzx r0, r8, r9
cmpwi r0, 0
beq _boatChosen
mr r26, r9
_boatChosen:
lwz r0, 0x18(r27)
cmpw r0, r26
beq _boatCollectDone
stw r26, 0x18(r27)
li r0, 1
stw r0, 0x50(r27)
_boatCollectDone:
lmw r24, 0x10(r1)
lwz r0, 0x34(r1)
mtlr r0
addi r1, r1, 0x30
blr

_boatSyncMenu:
lwz r3, 0x2C(r27)
cmpwi r3, 0
beqlr
lwz r0, 4(r3)
lwz r11, 0x60(r27)
cmpw r0, r11
bnelr
lwz r0, 0x18(r27)
cmplwi r0, 61
bgelr
# Menu-originated changes are already queued by the game. Do not restart or
# cancel its carousel when our TV copy follows that same selection.
lwz r9, 0xAC(r3)
cmpw r0, r9
beqlr
stw r9, 0xB0(r3)
stw r0, 0xAC(r3)
# Match the native next-chart action at 0x0269B9F4: retain the old chart in
# +B0, queue the new one in +AC, and request the forward carousel with +B8.
# Leave +B4 (last processed chart) intact. MenuMap's update at 0x0269C4E4
# refreshes caption/art and completes the carousel, returning to slot zero.
# Calling the initializer or clearing +B8 bypasses/stalls that lifecycle,
# so later L3 presses can update the caption while an old slot stays visible.
li r0, 1
stw r0, 0xB8(r3)
blr

_boatEnsureTreasure:
lwz r0, 0x20(r27)
cmpwi r0, 0
bnelr
lwz r0, 0x5C(r27)
cmpwi r0, 0
bnelr
lwz r0, 0x64(r27)
cmpwi r0, 0
beqlr
lwz r0, 0x68(r27)
cmpwi r0, 0
beqlr
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
li r0, 1
stw r0, 0x5C(r27)
lis r4, 0x1019
lwz r4, -0x3BFC(r4)
lwz r4, 0x10(r4)
li r3, 0x94
li r5, 4
bl 0x0273B90C
cmpwi r3, 0
beq _boatCreateDone
bl 0x026EC9FC
stw r3, 0x20(r27)
li r4, 0
li r5, 0
li r6, 0
bl 0x026ED008
cmpwi r3, 0
beq _boatCreateDone
lwz r3, 0x20(r27)
bl 0x026ED8D8 # native open presentation, only used for verified readable charts
lwz r3, 0x20(r27)
lwz r7, 0x6C(r3)
stw r7, 0x24(r27)
cmpwi r7, 0
beq _boatCreateUnattached
lwz r8, 0x44(r30)
lwz r8, 4(r8)
lwz r8, 0x0C(r8)
lwz r9, 0x0C(r7)
stw r9, 0x28(r27)
bl _boatReparent
cmpwi r0, 0
beq _boatCreateUnattached
# The added title is the last child of the private square. Its native textbox
# is the last child of the two-piece ribbon, inside N_BoatTitle.
lwz r8, 0x24(r27)
lwz r8, 0x18(r8)
lwz r0, 0x80(r8)
lis r9, 0x4E5F
ori r9, r9, 0x426F # N_Bo
cmpw r0, r9
bne _boatNoTitle
lwz r8, 0x14(r8)
lwz r8, 0x18(r8)
stw r8, 0xA8(r27)
_boatNoTitle:
li r0, 0
stw r0, 0x5C(r27)
li r0, -1
stw r0, 0x80(r27) # first preparation frame must not consume the entrance clock
b _boatCreateDone
_boatCreateUnattached:
lwz r3, 0x20(r27)
li r0, 0
stw r0, 0x20(r27)
stw r0, 0x24(r27)
stw r0, 0x28(r27)
stw r0, 0xA8(r27)
li r4, 1
bl 0x026EC738
_boatCreateDone:
lwz r0, 0x14(r1)
