# r7 child, r8 destination parent; intrusive pane lists, exact count accounting.
_boatReparent:
cmpwi r7, 0
beq _boatReparentRejected
cmpwi r8, 0
beq _boatReparentRejected
lwz r9, 0x0C(r7)
cmpwi r9, 0
beq _boatReparentRejected
lwz r10, 0(r7)
lwz r11, 4(r7)
cmpwi r10, 0
beq _boatReparentRejected
cmpwi r11, 0
beq _boatReparentRejected
lwz r0, 4(r10)
cmpw r0, r7
bne _boatReparentRejected
lwz r0, 0(r11)
cmpw r0, r7
bne _boatReparentRejected
lwz r0, 0x10(r9)
cmpwi r0, 0
beq _boatReparentRejected
addi r6, r8, 0x14
lwz r5, 0(r6)
cmpwi r5, 0
beq _boatReparentRejected
lwz r0, 4(r5)
cmpw r0, r6
bne _boatReparentRejected
lwz r5, 4(r6)
cmpwi r5, 0
beq _boatReparentRejected
lwz r0, 0(r5)
cmpw r0, r6
bne _boatReparentRejected
stw r10, 0(r11)
stw r11, 4(r10)
lwz r10, 0x10(r9)
addi r10, r10, -1
stw r10, 0x10(r9)
addi r9, r8, 0x14
lwz r10, 4(r9)
stw r7, 0(r10)
stw r10, 4(r7)
stw r9, 0(r7)
stw r7, 4(r9)
stw r8, 0x0C(r7)
lwz r10, 0x10(r8)
addi r10, r10, 1
stw r10, 0x10(r8)
li r0, 1 # success: the child is linked to the destination
blr
_boatReparentRejected:
li r0, 0 # no writes to a detached, destroying, or inconsistent pane
blr

_boatPresent:
mflr r0
stwu r1, -0x30(r1)
stw r0, 0x34(r1)
stmw r27, 0x1C(r1)
lis r27, _boatState@ha
addi r27, r27, _boatState@l
li r0, 0
stw r0, 0x54(r27)
bl _boatFindDecor
lwz r8, 0x24(r27)
cmpwi r8, 0
beq _boatPresentationGate
lbz r0, 0x44(r8)
rlwinm r0, r0, 0, 0, 30
stb r0, 0x44(r8)
_boatPresentationGate:
bl _boatResolvePresentation
cmpwi r3, 2
beq _boatPresentReturn # native HUD hides everything; retain slide state only
cmpwi r3, 0
beq _boatPresentDone
cmpwi r3, 5
bne _boatStillAboard
bl _boatExitPresent
b _boatPresentDone
_boatStillAboard:
bl _boatSlideCompass
lis r8, _boatPresentationState@ha
addi r8, r8, _boatPresentationState@l
lwz r0, 4(r8)
cmpwi r0, 1
beq _boatPresentDone
lis r8, _frameState@ha
addi r8, r8, _frameState@l
lwz r0, 8(r8)
cmpwi r0, 0
beq _boatPresentDone
lwz r29, 12(r8) # current animated square, resolved even with background Off
cmpwi r29, 0
beq _boatPresentDone
lwz r0, 0x1C(r27)
cmpwi r0, 0
beq _boatPresentDone
bl _boatEnsureTreasure
lwz r0, 0x5C(r27)
cmpwi r0, 0
bne _boatPresentDone
lwz r3, 0x20(r27)
cmpwi r3, 0
beq _boatPresentDone
lwz r4, 0x18(r27)
lwz r0, 0x3C(r27)
cmpw r4, r0
beq _boatUpdateTreasure
stw r4, 0x3C(r27)
bl 0x026ED5F4
_boatUpdateTreasure:
bl _boatUpdateTitle
lwz r3, 0x20(r27)
bl 0x026ED334
lwz r3, 0x20(r27)
lwz r3, 0x44(r3)
lwz r3, 4(r3)
bl 0x026FB178
lwz r3, 0x20(r27)
lwz r3, 0x44(r3)
lwz r3, 4(r3)
bl 0x026FB300
# Never show live position/direction on a treasure chart. Hide the entire
# private LinkPos widget AFTER native updates; the GamePad instance is intact.
lwz r8, 0x20(r27)
lwz r8, 0x60(r8)
lbz r0, 0x44(r8)
rlwinm r0, r0, 0, 0, 30
stb r0, 0x44(r8)
bl _boatTreasureSlide
lwz r0, 0x84(r27)
lwz r9, 0x8C(r27)
or. r0, r0, r9
beq _boatPresentDone
lwz r28, 0x24(r27)
lfs f0, 0x1C(r29)
# Remove the local slide: this second panel has its own 200 ms entrance/exit.
lfs f1, 0x64(r31)
fsubs f0, f0, f1
lfs f1, 0x3C(r29)
fadds f0, f0, f1
lfs f1, 0x78(r27)
fadds f0, f0, f1
stfs f0, 0x7C(r27)
stfs f0, 0x1C(r28)
# Rise from below, descend on close. Include the ribbon's top in the travel.
lfs f0, 0x20(r29)
lfs f1, 0x3C(r29)
lis r8, _boatExitState@ha
addi r8, r8, _boatExitState@l
stfs f0, 4(r8) # retain the last valid presentation independently of the foot map
stfs f1, 8(r8)
lfs f2, 0x9C(r27)
fmuls f1, f1, f2
fadds f1, f1, f0
lfs f2, 0xA0(r27)
fadds f1, f1, f2
lfs f2, 0x90(r27)
fmuls f1, f1, f2
fsubs f0, f0, f1
stfs f0, 0xB0(r27)
stfs f0, 0x20(r28)
lfs f0, 0x3C(r29)
lfs f1, 0x44(r27)
fmuls f0, f0, f1
stfs f0, 0x34(r28)
stfs f0, 0x38(r28)
lis r8, _unifiedOpacityState@ha
addi r8, r8, _unifiedOpacityState@l
lwz r0, 4(r8)
stb r0, 0x45(r28)
lbz r0, 0x44(r28)
ori r0, r0, 0x13
stb r0, 0x44(r28)
li r0, 1
stw r0, 0x54(r27)
mr r3, r28
bl _dungeonMatrices
bl _boatDecorate
_boatPresentDone:
lwz r0, 0x54(r27)
cmpwi r0, 0
bne _boatPresentReturn
# Unavailable, user-closed or completed exit: clear presentation only.
# Native HUD suspension returns above without forgetting the selected mode.
li r0, 0
lis r8, _boatExitState@ha
addi r8, r8, _boatExitState@l
stw r0, 0(r8)
stw r0, 0x80(r27)
stw r0, 0x84(r27)
stw r0, 0x8C(r27)
