# Shared map policy: 200 ms entrance, 250 ms smooth exit.
# Separate normalized progress allows the right panel to leave the viewport
# completely without changing the existing local map's motion or distance.
_boatTreasureSlide:
lwz r0, 0x80(r27)
cmpwi r0, -1
bne _boatTreasureSlidePrepared
# Finish native creation/title/layout work while still hidden. Start the
# 200 ms entrance on the following HUD update, after this preparation frame.
li r0, 0
stw r0, 0x80(r27)
blr
_boatTreasureSlidePrepared:
cmpwi r0, 0
bne _boatTreasureSlideTarget
li r0, 1
stw r0, 0x80(r27)
lfs f0, 0x48(r27)
stfs f0, 0x90(r27)
li r0, 0
stw r0, 0x84(r27)
stw r0, 0x8C(r27)
_boatTreasureSlideTarget:
li r8, 0
lwz r0, 4(r27)
cmpwi r0, 2
bne _boatTreasureSlideClock
li r8, 1
_boatTreasureSlideClock:
.int 0x7CCC42E6 # mftb r6
lwz r0, 0x84(r27)
cmpw r0, r8
beq _boatTreasureSlideAdvance
stw r8, 0x84(r27)
stw r6, 0x88(r27)
# On closing, share the local panel's start tick so both leave together.
cmpwi r8, 0
bne _boatTreasureSlideStart
lis r9, _boatExitState@ha
addi r9, r9, _boatExitState@l
lwz r0, 0(r9)
cmpwi r0, 0
bne _boatTreasureSlideStart # disembarking has its own fresh exit clock
lwz r0, 0x5C(r31)
stw r0, 0x88(r27)
_boatTreasureSlideStart:
lfs f0, 0x90(r27)
stfs f0, 0x94(r27)
lfs f0, 0x48(r27)
cmpwi r8, 0
beq _boatTreasureSlideDestination
lfs f0, 0x4C(r27)
_boatTreasureSlideDestination:
stfs f0, 0x98(r27)
li r0, 1
stw r0, 0x8C(r27)
_boatTreasureSlideAdvance:
lwz r0, 0x8C(r27)
cmpwi r0, 0
beqlr
lwz r9, 0x88(r27)
subf r9, r9, r6
lwz r0, 0x84(r27)
cmpwi r0, 0
beq _treasureExitTiming
lis r10, 0x00BD
ori r10, r10, 0xAF92 # entrance: original 200 ms
lis r11, 1
ori r11, r11, 0x7B5F
b _treasureTimingReady
_treasureExitTiming:
lis r10, 0x00ED
ori r10, r10, 0x1B77 # exit: 15,539,063 ticks = 250 ms
lis r11, 1
ori r11, r11, 0xDA37
_treasureTimingReady:
cmplw r9, r10
bge _boatTreasureSlideFinish
divwu r9, r9, r11
slwi r9, r9, 2
lis r10, _slideEase@ha
addi r10, r10, _slideEase@l
cmpwi r0, 0
bne _treasureSampleReady
lis r10, _mapExitEase@ha
addi r10, r10, _mapExitEase@l
_treasureSampleReady:
lfsx f2, r10, r9
lfs f0, 0x94(r27)
lfs f1, 0x98(r27)
fsubs f1, f1, f0
fmuls f1, f1, f2
fadds f0, f0, f1
stfs f0, 0x90(r27)
blr
_boatTreasureSlideFinish:
li r0, 0
stw r0, 0x8C(r27)
lfs f0, 0x98(r27)
stfs f0, 0x90(r27)
blr

