_boatExitState:
.int 0 # active disembark exit; never permits new charts while on foot
.float 0 # last valid resting Y
.float 0 # last valid square width
.int 0 # last drawn treasure alpha
.int 0 # last drawn background visible bit
.int 0 # last drawn parchment visible bit
.int 0 # owning HUD; invalidate on replacement/loading

# Tail-called from _boatBegin with r12=boat state, r30=current HUD.
# Keep the existing slide progress, so disembarking mid-slide is continuous.
_boatStartExit:
lwz r0, 0x54(r12)
cmpwi r0, 0
beqlr
lwz r8, 0x24(r12)
cmpwi r8, 0
beqlr
