stw r0, 0(r9)
stw r30, 0x18(r9)
lbz r0, 0x45(r8)
stw r0, 0x0C(r9)
li r0, 0
stw r0, 0x10(r9)
stw r0, 0x14(r9)
lwz r8, 0x70(r12)
cmpwi r8, 0
beq _boatExitCaptureRim
