# Finish only the already drawn treasure view. Foot visibility, discovery or
# map resizing must not reposition it or cut off the remainder of its exit.
# The normal sea/HUD guard is still required; no tail over pause/loading.
_boatExitPresent:
mflr r0
stwu r1, -0x18(r1)
stw r0, 0x1C(r1)
stw r28, 0x10(r1)
stw r29, 0x14(r1)
lis r28, _boatExitState@ha
addi r28, r28, _boatExitState@l
lwz r0, 0(r28)
cmpwi r0, 0
beq _boatExitReturn
lwz r0, 0x18(r28)
cmpw r0, r30
bne _boatExitReturn
