cmpwi r3, 0
beq _boatExitReturn
lwz r29, 0x24(r27)
cmpwi r29, 0
beq _boatExitReturn
bl _boatTreasureSlide
lwz r0, 0x8C(r27)
cmpwi r0, 0
beq _boatExitReturn
lfs f0, 4(r28)
lfs f1, 8(r28)
lfs f2, 0x9C(r27)
fmuls f1, f1, f2
fadds f1, f1, f0
lfs f2, 0xA0(r27)
fadds f1, f1, f2
lfs f2, 0x90(r27)
fmuls f1, f1, f2
fsubs f0, f0, f1
stfs f0, 0xB0(r27)
stfs f0, 0x20(r29)
lwz r0, 0x0C(r28)
