stb r0, 0x44(r29)
li r0, 1
stw r0, 0x54(r27)
mr r3, r29
bl _dungeonMatrices
# Decoration geometry and per-piece alpha remain the last drawn values.
# Only translate Y, keeping the ribbon (a child of treasure) and all edges
# aligned. _boatFindDecor resolved and hid them earlier in this HUD tick.
lwz r3, 0x70(r27)
cmpwi r3, 0
beq _boatExitDrawRim
lwz r0, 0xB0(r27)
stw r0, 0x20(r3)
lbz r0, 0x44(r3)
lwz r9, 0x10(r28)
