# ResourceGet helper: r26 accessor, r28 requested name, r29 size pointer,
# r30 original result. Return a private replacement or 0 for native behavior.
# The temporary COPY source pointers are cleared before returning.
_boatTitleResourceState:
.int 0x42545231 # BTR1
.int 0 # ready, -1 incompatible
.int 0
.int 0 # +0C native TreMap bytes during assembly only
.int 0 # +10 native MenuMap bytes during assembly only

_boatTitleLayout:
lis r8, _boatState@ha
addi r8, r8, _boatState@l
lwz r0, 0xA4(r8)
cmpwi r0, 0
li r3, 0
beqlr
mflr r0
stwu r1, -0x18(r1)
stw r0, 0x1C(r1)
stw r31, 0x14(r1)
mr r3, r28
lis r4, _boatTreSourceName@ha
addi r4, r4, _boatTreSourceName@l
bl _resourceNameEqual
cmpwi r3, 0
beq _boatTitleResourceNone
lis r31, _boatTitleResourceState@ha
addi r31, r31, _boatTitleResourceState@l
lwz r0, 4(r31)
cmpwi r0, 1
beq _boatTitleResourceReady
cmpwi r0, -1
beq _boatTitleResourceNone
stw r30, 0x0C(r31)
mr r3, r30
# Layout::Build normally requests its BFLYT with a null out-size argument.
# Validate its declared size against our exact source spec before hashing.
lwz r4, 0x0C(r30)
lis r5, _boatTreSpec@ha
addi r5, r5, _boatTreSpec@l
bl _resourceValidate
cmpwi r3, 0
beq _boatTitleResourceRejected
mr r3, r26
lis r4, 0x626C
ori r4, r4, 0x7974
lis r5, _boatMenuSourceName@ha
addi r5, r5, _boatMenuSourceName@l
addi r6, r1, 8
bl _resourceOriginal
stw r3, 0x10(r31)
lwz r4, 8(r1)
lis r5, _boatMenuSpec@ha
addi r5, r5, _boatMenuSpec@l
bl _resourceValidate
cmpwi r3, 0
beq _boatTitleResourceRejected
lis r3, _boatTitleBuffer@ha
addi r3, r3, _boatTitleBuffer@l
lis r4, _boatTitleProgram@ha
addi r4, r4, _boatTitleProgram@l
bl _resourceAssemble
li r0, 1
stw r0, 4(r31)
li r0, 0
stw r0, 0x0C(r31)
stw r0, 0x10(r31)
_boatTitleResourceReady:
