_boatTitleResourceReturn:
lwz r31, 0x14(r1)
lwz r0, 0x1C(r1)
mtlr r0
addi r1, r1, 0x18
blr

# Preserve visual continuity when a boat policy changes the requested view.
# r31=map, r27=boat. All native calls affect the PRIVATE local-map object only.
_boatShrinkToCompact:
lwz r3, 4(r31)
lwz r0, 0x144(r3)
cmpwi r0, 1
beqlr
lwz r0, 0x90(r31)
cmpwi r0, 0
bne _boatShrinkRunning # already shrinking: do not restart it every tick
mflr r0
stwu r1, -0x20(r1)
stw r0, 0x24(r1)
# Retain the current frame, even if embarkation interrupts an enlargement.
lwz r8, 0x44(r3)
lwz r8, 0xD4(r8)
lwz r8, 0x10(r8)
lwz r8, 0x14(r8) # active animation slot 5
lwz r8, 0x34(r8)
lfs f0, 0x0C(r8)
stfs f0, 8(r1)
li r0, 3 # use the reverse clip path, not compact initial-pose setup
stw r0, 0x144(r3)
li r4, 8
bl _playOwnedZoom
lwz r3, 4(r31)
lwz r3, 0x44(r3)
lwz r3, 0xD4(r3)
lwz r8, 0x10(r3)
lwz r8, 0x14(r8)
lis r9, _boatShrinkSpeed@ha
lfs f1, _boatShrinkSpeed@l(r9)
stfs f1, 4(r8) # native 15-frame clip / 2.5 = six game ticks (200 ms)
lfs f1, 8(r1)
li r4, 9
li r5, 5
bl 0x0200579C # native seek; reverse from the current pose, without jumping
lwz r0, 0x24(r1)
mtlr r0
addi r1, r1, 0x20
blr
_boatShrinkRunning:
lwz r8, 0x44(r3)
lwz r8, 0xD4(r8)
lwz r8, 0x10(r8)
lwz r8, 0x14(r8)
lis r9, _boatShrinkSpeed@ha
lfs f1, _boatShrinkSpeed@l(r9)
stfs f1, 4(r8)
blr
_boatShrinkSpeed:
.float -2.5

# Eligibility never becomes true for the current unknown sector. Only the old
# discovered image, already on screen, survives for its bounded 200 ms exit.
# The caller has selected effective mode 0 and retains the player's request.
_boatKeepClosingPlan:
lwz r0, 0x6C(r27)
cmpwi r0, 0
bnelr
lwz r0, 0x48(r31)
cmpwi r0, 1
bnelr
lwz r8, 8(r31)
cmpwi r8, 0
beqlr
lbz r0, 0x44(r8)
andi. r0, r0, 1
beqlr # never resurrect a picture already hidden by a cinematic/menu
lwz r0, 0x54(r31)
cmpwi r0, 0
beqlr
lwz r0, 0x58(r31)
lwz r8, 0x60(r31)
or. r0, r0, r8
beqlr # close finished: no stale picture can remain on screen
li r0, 1
stw r0, 0xBC(r27)
stw r0, 0x2C(r31) # draw permission only, not discovery or geometric coverage
blr


# Island-only wind hint. Uses the same native wind getter as MenuMap_00,
# independent of menu updates, selected chart, or background opacity.
# Shares the common map root alpha, including activity and native HUD fades.
# Position/scale follows the actual island square's final animated matrix.
_windState:
.int 0x574E4430 # WND0
.int $showWindArrow
.float 255 # reserved compatibility field; no separate wind opacity
.int 0 # live pane diagnostic; never dereferenced across ticks
.int 0 # eligible/visible this tick
.int 0 # native 16-bit wind heading
.float 0 # rotation degrees
.float 0.416 # tip nearly touches north/east edge: ~0.5% square gap, stroke included
.float 0.0028125 # 0.18/64: child texture display size relative to map square
.float 0.0054931640625 # 360/65536
.int 0x43300000
.int 0
.float 0.5
.int 0 # effective alpha diagnostic
.float 0 # final square size diagnostic

_updateWindArrow:
mflr r0
stwu r1, -0x30(r1)
stw r0, 0x34(r1)
stmw r27, 0x1C(r1)
lis r27, _windState@ha
addi r27, r27, _windState@l
li r0, 0
stw r0, 0x0C(r27)
stw r0, 0x10(r27)
stw r0, 0x34(r27)
# Resolve our pane in this HUD instance; no pointer into a former stage/HUD.
lis r8, _hudPanes@ha
addi r8, r8, _hudPanes@l
lwz r28, 8(r8)
lwz r29, 0x18(r8)
cmpwi r29, 0
beq _windDone
_windFound:
stw r29, 0x0C(r27)
lbz r0, 0x44(r29)
rlwinm r0, r0, 0, 0, 30
stb r0, 0x44(r29)
lwz r0, 4(r27)
cmpwi r0, 0
beq _windDone
# Explicit current-stage check excludes all dungeons, even outdoor rooms.
lis r8, 0x1047
lwz r8, 0x41E4(r8)
lis r0, 0x7365
ori r0, r0, 0x6100
cmpw r8, r0
bne _windDone
lwz r0, 0x2C(r31) # interaction eligibility stays false outside coverage
lwz r8, 0x60(r31)
or r0, r0, r8 # wind follows the complete map during its close slide
cmpwi r0, 0
beq _windDone
lwz r8, 8(r31)
cmpwi r8, 0
beq _windDone
lbz r0, 0x44(r8)
andi. r0, r0, 1 # user visibility, including the animated closing interval
beq _windDone
lbz r9, 0x45(r8) # same global opacity/HUD fade as island minimap
stw r9, 0x18(r1)
lwz r10, 0x10(r8)
cmplwi r10, 64
bgt _windDone
lwz r8, 0x14(r8)
_windFindMapBase:
cmpwi r10, 0
beq _windDone
lwz r0, 0x80(r8)
lis r11, 0x505F
ori r11, r11, 0x4D61
cmpw r0, r11
bne _windNextBase
lwz r0, 0x84(r8)
lis r11, 0x7042
ori r11, r11, 0x6173
cmpw r0, r11
bne _windNextBase
lwz r0, 0x88(r8)
lis r11, 0x655F
ori r11, r11, 0x3030
cmpw r0, r11
beq _windGeometry
_windNextBase:
lwz r8, 0(r8)
addi r10, r10, -1
b _windFindMapBase
_windGeometry:
lfs f0, 0x3C(r8)
lfs f1, 0x48(r8)
fmuls f0, f0, f1
stfs f0, 0x38(r27)
lfs f1, 0x1C(r27)
fmuls f1, f0, f1
lfs f2, 0x54(r8)
fadds f2, f2, f1
stfs f2, 0x1C(r29)
lfs f2, 0x64(r8)
fadds f2, f2, f1
stfs f2, 0x20(r29)
lfs f1, 0x20(r27)
fmuls f0, f0, f1
stfs f0, 0x34(r29)
stfs f0, 0x38(r29)
# Native getter derives the actual heading from the world wind vector.
# The original menu applies the equivalent angle, rounded to eight directions.
bl 0x0257DAD0
clrlwi r3, r3, 16
stw r3, 0x14(r27)
lis r0, 0x4330
stw r0, 8(r1)
stw r3, 0x0C(r1)
lfd f0, 8(r1)
lfd f1, 0x28(r27)
fsub f0, f0, f1
frsp f0, f0
lfs f1, 0x24(r27)
fmuls f0, f0, f1
stfs f0, 0x18(r27)
stfs f0, 0x30(r29)
# Root already combines the shared activity alpha and the native HUD fade.
# Copy it once: a second multiplication would incorrectly square the opacity.
lwz r9, 0x18(r1)
stw r9, 0x34(r27)
stb r9, 0x45(r29)
cmpwi r9, 0
beq _windDone
# The owned island root is appended after Main construction. Put this hint
# after it in the SAME HUD list; no extra draw pass or GamePad interaction.
lwz r8, 0x18(r28)
cmpw r8, r29
beq _windShow
lwz r9, 0(r29)
lwz r10, 4(r29)
stw r9, 0(r10)
stw r10, 4(r9)
addi r9, r28, 0x14
lwz r8, 4(r9)
stw r29, 0(r8)
stw r8, 4(r29)
stw r9, 0(r29)
stw r29, 4(r9)
_windShow:
li r0, 1
stw r0, 0x10(r27)
lbz r0, 0x44(r29)
ori r0, r0, 0x13
stb r0, 0x44(r29)
mr r3, r29
bl _updateWindWave
mr r3, r29
bl _dungeonMatrices
_windDone:
lmw r27, 0x1C(r1)
lwz r0, 0x34(r1)
mtlr r0
addi r1, r1, 0x30
blr


# Current-frame common alpha, applied after activity computation. Only private
# minimap roots are touched. HUD controls and GamePad roots are not targeted.
_unifiedOpacityState:
.int 0x554F5041 # UOPA
.int 0 # common opacity after native HUD modulation
.int 0 # island root diagnostic
.int 0 # number of dungeon roots updated

_applyUnifiedMapAlpha:
mflr r0
stwu r1, -0x28(r1)
stw r0, 0x2C(r1)
stmw r27, 0x14(r1)
lis r28, _unifiedOpacityState@ha
addi r28, r28, _unifiedOpacityState@l
li r0, 0
stw r0, 8(r28)
stw r0, 12(r28)
lis r8, _activityState@ha
addi r8, r8, _activityState@l
lwz r9, 0x24(r8)
bl _mapHudFadeAlpha
mr r27, r9
stw r27, 4(r28)
