addi r8, r8, _mapState@l
lwz r3, 8(r8)
cmpwi r3, 0
beq _unifiedDungeonRoots
stw r3, 8(r28)
bl _unifiedRootAlpha
_unifiedDungeonRoots:
lis r8, _dungeonState@ha
addi r8, r8, _dungeonState@l
lwz r0, 0x0C(r8)
cmpwi r0, 1
bne _unifiedAlphaDone
lwz r0, 0x10(r8) # same context gate as _dungeonHudDraw
cmpwi r0, 0
beq _unifiedAlphaDone # no private dungeon component can draw in this context
lwz r9, 0x14(r8) # same user-visible OR sliding guard as _dungeonHudDraw
lwz r0, 0x44(r8)
or. r0, r0, r9
beq _unifiedAlphaDone # fully closed: defer alpha propagation until reopening
lwz r29, 4(r8)
cmpwi r29, 0
beq _unifiedAlphaDone
addi r29, r29, 0xA0
li r31, 142 # same bounded floor/marker component array as the native-map tick
_unifiedDungeonLoop:
lwz r8, 0(r29)
cmpwi r8, 0
beq _unifiedDungeonNext
lwz r8, 0x44(r8)
cmpwi r8, 0
beq _unifiedDungeonNext
lwz r8, 4(r8)
lwz r3, 0x0C(r8)
bl _unifiedDungeonMarkerAlpha
lwz r9, 12(r28)
addi r9, r9, 1
stw r9, 12(r28)
_unifiedDungeonNext:
addi r29, r29, 4
addi r31, r31, -1
cmpwi r31, 0
bne _unifiedDungeonLoop
_unifiedAlphaDone:
lmw r27, 0x14(r1)
lwz r0, 0x2C(r1)
mtlr r0
addi r1, r1, 0x28
blr

_unifiedRootAlpha:
lis r8, _unifiedAlphaStats@ha
addi r8, r8, _unifiedAlphaStats@l
lwz r11, 4(r8)
addi r11, r11, 1
stw r11, 4(r8)
lbz r0, 0x45(r3)
cmpw r0, r27
bne _unifiedRootChanged
lbz r0, 0x46(r3)
cmpw r0, r27 # require the already-computed effective alpha too
bne _unifiedRootChanged
lwz r11, 12(r8)
addi r11, r11, 1
stw r11, 12(r8)
blr # native/owned geometry was already updated earlier in this HUD tick
_unifiedRootChanged:
lwz r11, 8(r8)
addi r11, r11, 1
stw r11, 8(r8)
stb r27, 0x45(r3)
lbz r0, 0x44(r3)
ori r0, r0, 0x12 # propagate alpha; preserve the existing visible/hidden bit
stb r0, 0x44(r3)
b _dungeonMatrices

_unifiedAlphaStats:
.int 0x55415354 # UAST
.int 0 # checks
.int 0 # alpha/matrix updates
.int 0 # unchanged roots (matrix recursion avoided)

# r8=AFAD, r9=result; r3 stays the backdrop pane. Caller reserves stack+8..15.
# Idle alpha=min(background idle, overall). Activity uses the same ratio as
# the rest of the block; its timings, eligibility and HUD fade stay shared.
_backgroundCommonAlpha:
li r9, 0
lfs f0, 0x54(r8)
lfs f3, 0x2C(r8)
fcmpu cr0, f0, f3
blelr # zero overall opacity: no divide, nothing visible
lfs f1, 0x58(r8)
fcmpu cr0, f1, f0
ble _backgroundMinClamped
fmr f1, f0
_backgroundMinClamped:
fsubs f2, f0, f1
lfs f3, 4(r8)
fmuls f2, f2, f3
fadds f2, f2, f1
fdivs f2, f2, f0
lfs f1, 0x40(r8)
fcmpu cr0, f1, f0
ble _backgroundIdleClamped
fmr f1, f0
_backgroundIdleClamped:
fmuls f0, f1, f2
lfs f1, 0x3C(r8)
fadds f0, f0, f1
fctiwz f0, f0
stfd f0, 8(r1)
lwz r9, 0x0C(r1)
blr


# Permanent exterior parchment rim. No world/menu pointer survives a HUD tick.
_frameState:
