lfs f0, 0x3C(r8)
stfs f0, 0x1C(r27)
lfs f1, 0x20(r27)
fmuls f0, f0, f1
stfs f0, 0x3C(r29)
lfs f0, 0x40(r8)
fmuls f0, f0, f1
stfs f0, 0x40(r29)
lfs f0, 0x1C(r8)
stfs f0, 0x1C(r29)
lfs f0, 0x20(r8)
stfs f0, 0x20(r29)
