# A cross-family resize uses the last actually drawn square, including an
# interrupted resize. Its lower-left anchor remains the usual (-616,-336).
_familySizeState:
.int 0x46535A45 # FSZE
.int 0 # +04 pending island resize, prepared by the actual family transition
.float 0 # +08 previous visible square width
.int 0, 0 # +0C..10 stage identity; values only, never pointers
.int 0 # +14 island resize active
.int 0 # +18 island resize start clock
.float 195.7 # +1C destination effective width
.float 195.7 # +20 last effective width, for retargeting a deferred boarding edge

# Leaf predicate: r10=state; r0=1 only in the captured stage.
_familySizeSameStage:
lis r8, 0x1047
lwz r9, 0x41E4(r8)
lwz r0, 0x0C(r10)
cmpw r9, r0
bne _familySizeDifferentStage
lwz r9, 0x41E8(r8)
lwz r0, 0x10(r10)
cmpw r9, r0
bne _familySizeDifferentStage
li r0, 1
blr
_familySizeDifferentStage:
li r0, 0
stw r0, 4(r10)
stw r0, 0x14(r10)
blr

# r31=private island state, r7=validated private root. All descendants, the
# backdrop, frame and wind consume the resulting matrices in this same tick.
# The native child clip continues normally; divide out its current scale.
_islandFamilySize:
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
lis r10, _familySizeState@ha
addi r10, r10, _familySizeState@l
lwz r0, 4(r10)
lwz r9, 0x14(r10)
or r0, r0, r9
cmpwi r0, 0
beq _islandFamilySizeDone
bl _familySizeSameStage
cmpwi r0, 0
beq _islandFamilySizeDone
lwz r0, 0x2C(r31)
cmpwi r0, 0
beq _islandFamilySizeDone # allow a pending handoff to reach dungeon guards
.int 0x7CCC42E6 # mftb r6
lwz r0, 0x7C(r31)
cmpwi r0, 0
beq _islandFamilySizePolicyReady
lis r11, _dungeonState@ha
addi r11, r11, _dungeonState@l
lfs f0, 0x50(r11)
lfs f1, 0x1C(r10)
fcmpu cr0, f0, f1
beq _islandFamilySizePolicyReady
stfs f0, 0x1C(r10)
lwz r0, 0x14(r10)
cmpwi r0, 0
beq _islandFamilySizeRetarget
lfs f0, 0x20(r10)
stfs f0, 8(r10)
_islandFamilySizeRetarget:
li r0, 1
stw r0, 4(r10) # restart below from the current effective width
_islandFamilySizePolicyReady:
lwz r0, 4(r10)
cmpwi r0, 1
bne _islandFamilySizeAdvance
li r0, 0
stw r0, 4(r10)
li r0, 1
stw r0, 0x14(r10)
stw r6, 0x18(r10)
_islandFamilySizeAdvance:
lwz r0, 0x14(r10)
cmpwi r0, 0
beq _islandFamilySizeDone
lwz r9, 0x18(r10)
subf r9, r9, r6
lis r8, 0x00BD
ori r8, r8, 0xAF92 # existing 200 ms resize interval
lis r11, _dungeonState@ha
addi r11, r11, _dungeonState@l
lfs f0, 0x68(r11)
cmplw r9, r8
bge _islandFamilySizeFinish
lis r8, 1
ori r8, r8, 0x7B5F
divwu r9, r9, r8
slwi r9, r9, 2
lis r8, _slideEase@ha
addi r8, r8, _slideEase@l
lfsx f0, r8, r9
b _islandFamilySizeWidth
_islandFamilySizeFinish:
li r0, 0
stw r0, 0x14(r10)
_islandFamilySizeWidth:
lfs f1, 8(r10)
lfs f2, 0x1C(r10)
fsubs f3, f2, f1
fmuls f3, f3, f0
fadds f1, f1, f3 # current effective square width
stfs f1, 0x20(r10)
lfs f2, 0x50(r11)
fdivs f2, f1, f2
lfs f3, 0x80(r31)
fmuls f2, f2, f3
lwz r8, 4(r31)
lwz r8, 0x94(r8)
cmpwi r8, 0
beq _islandFamilySizeDone
lfs f3, 0x34(r8)
lfs f4, 0x78(r31)
fcmpu cr0, f3, f4
ble _islandFamilySizeDone
fdivs f2, f2, f3
stfs f2, 0x34(r7)
stfs f2, 0x38(r7)
lfs f2, 0x58(r11)
fmuls f1, f1, f2
lfs f2, 0x5C(r11)
fadds f2, f2, f1
stfs f2, 0x1C(r7)
lfs f2, 0x60(r11)
fadds f2, f2, f1
stfs f2, 0x20(r7)
b _islandFamilySizeDone
_islandFamilySizeClear:
li r0, 0
stw r0, 4(r10)
stw r0, 0x14(r10)
_islandFamilySizeDone:
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
blr

# UI preference, retained across disembarking and private layout teardown.
# Set only in the marine input path; native dungeon boating never writes it.
_marinePreference:
.int 0 # initialized by the first eligible marine input tick
.int 1 # requested mode: 0 hidden/compass, 1 local, 2 local+treasure

# Numeric end-of-HUD presentation snapshot. HUD identity is compared only.
_mapPresentationSnapshot:
.int 0, 0 # +00 HUD identity, +04 completed HUD tick
.int 0, 0 # +08..0C stage identity
.int 0 # +10 family: 0 suppressed/unavailable, 1 island, 2 dungeon
.float 1 # +14 normalized closed fraction
.float 0 # +18 actual square width
.int 0 # +1C geometric visibility; activity opacity does not change this
.int 0 # +20 final frame visible flag, diagnostic
.float 0, 1, 49 # +24 zero, +28 one, +2C offscreen clearance
.int 0, 1 # +30 last foot family, +34 last foot user visibility
.int 0 # +38 last active riding context; retained during HUD suppression
.float 0 # +3C actual horizontal offset, preserving the absolute first pose
.int 0 # +40 prior native marine compass context (riding AND sea HUD eligible)
.int 0 # +44 compass context provenance known (private atlas has initialized)

# r31=island, r7=private root. Preserve both and the caller's LR.
_prepareIslandPresentation:
lwz r0, 0x2C(r31)
cmpwi r0, 0
beqlr # uncovered foot departures retain the dedicated coverage handoff below
_islandPresentationEligible:
lis r12, _mapPresentationSnapshot@ha
addi r12, r12, _mapPresentationSnapshot@l
lwz r0, 0(r12)
cmpw r0, r30
bnelr
lis r11, _mapState@ha
addi r11, r11, _mapState@l
lwz r8, 0x14(r11)
lwz r9, 4(r12)
addi r9, r9, 1
cmpw r8, r9
bnelr
lis r8, 0x1047
lwz r9, 0x41E4(r8)
lwz r0, 8(r12)
cmpw r9, r0
bnelr
lwz r9, 0x41E8(r8)
lwz r0, 0x0C(r12)
cmpw r9, r0
bnelr
lwz r0, 0x10(r12)
cmpwi r0, 1
beqlr # same native family: Tower and ordinary island continuity stay intact
cmpwi r0, 0
bne _presentation1SourceReady
lwz r8, 0x7C(r11)
lwz r9, 0x38(r12)
cmpw r8, r9
beqlr # ordinary HUD resume, without changing foot/boat context
_presentation1SourceReady:
lwz r0, 0x1C(r12)
cmpwi r0, 0
beq _islandPresentationSlide
# Resize only a previously drawn square. An entrance from hidden uses the
# destination's own size, rather than exposing a stale source rectangle.
lis r10, _familySizeState@ha
addi r10, r10, _familySizeState@l
li r0, 1
stw r0, 4(r10)
lfs f0, 0x18(r12)
stfs f0, 8(r10)
lwz r0, 8(r12)
stw r0, 0x0C(r10)
lwz r0, 0x0C(r12)
stw r0, 0x10(r10)
li r0, 0
stw r0, 0x14(r10)
lis r11, _dungeonState@ha
addi r11, r11, _dungeonState@l
lfs f0, 0x50(r11)
lwz r0, 0x7C(r31)
cmpwi r0, 0
bne _islandPresentationSizeReady
lwz r8, 4(r31)
lwz r0, 0x144(r8)
cmplwi r0, 2
blt _islandPresentationSizeReady
lwz r0, 0x90(r31)
cmpwi r0, 0
bne _islandPresentationSizeReady
lfs f0, 0x54(r11)
_islandPresentationSizeReady:
stfs f0, 0x1C(r10)
_islandPresentationSlide:
lfs f1, 0x70(r31)
lwz r8, 4(r31)
lwz r0, 0x144(r8)
cmplwi r0, 2
blt _islandPresentationDistance
lfs f1, 0x74(r31)
_islandPresentationDistance:
lwz r8, 0x10(r31)
lwz r0, 0x4C(r31)
cmpwi r0, 2
bne _islandPresentationTarget
li r8, 0
_islandPresentationTarget:
# f1=negative full slide distance; r8=destination visibility.
lfs f0, 0x14(r12)
fmuls f2, f0, f1
lwz r0, 0x1C(r12)
cmpwi r0, 0
beq _presentation1StartReady
lfs f2, 0x3C(r12)
_presentation1StartReady:
stfs f2, 0x64(r31)
stfs f2, 0x68(r31)
li r0, 1
stw r0, 0x54(r31)
li r0, 0
stw r0, 0x60(r31)
lfs f3, 0x24(r12)
cmpwi r8, 0
bne _presentation1DesiredFraction
lfs f3, 0x28(r12)
_presentation1DesiredFraction:
mr r0, r8
fcmpu cr0, f0, f3
beq _presentation1PreviousReady
xori r0, r8, 1 # start only the needed entrance/exit from the real fraction
_presentation1PreviousReady:
stw r0, 0x58(r31)
lfs f3, 0x24(r12)
cmpwi r8, 0
bne _presentation1EndReady
fmr f3, f1
_presentation1EndReady:
stfs f3, 0x6C(r31)
blr

# Called only after native dungeon/Map/HUD eligibility passed.
_dungeonFamilySize:
lis r12, _mapPresentationSnapshot@ha
addi r12, r12, _mapPresentationSnapshot@l
lwz r0, 0(r12)
cmpw r0, r30
bnelr
lis r11, _mapState@ha
addi r11, r11, _mapState@l
lwz r8, 0x14(r11)
lwz r9, 4(r12)
addi r9, r9, 1
cmpw r8, r9
bnelr
lis r8, 0x1047
lwz r9, 0x41E4(r8)
lwz r0, 8(r12)
cmpw r9, r0
bnelr
lwz r9, 0x41E8(r8)
lwz r0, 0x0C(r12)
cmpw r9, r0
bnelr
lwz r0, 0x10(r12)
cmpwi r0, 2
beqlr # same native family: Tower and ordinary island continuity stay intact
cmpwi r0, 0
bne _presentation2SourceReady
lwz r8, 0x7C(r11)
lwz r9, 0x38(r12)
cmpw r8, r9
beqlr # ordinary HUD resume, without changing foot/boat context
_presentation2SourceReady:
lis r10, _familySizeState@ha
addi r10, r10, _familySizeState@l
li r0, 0
stw r0, 4(r10)
stw r0, 0x14(r10)
lwz r0, 0x1C(r12)
cmpwi r0, 0
beq _dungeonPresentationSlide
lfs f0, 0x18(r12)
stfs f0, 0x34(r31)
stfs f0, 0x38(r31)
li r0, 0
