lwz r8, 0x14(r31)
# f1=negative full slide distance; r8=destination visibility.
lfs f0, 0x14(r12)
fmuls f2, f0, f1
lwz r0, 0x1C(r12)
cmpwi r0, 0
beq _presentation2StartReady
lfs f2, 0x3C(r12)
_presentation2StartReady:
stfs f2, 0x3C(r31)
stfs f2, 0x48(r31)
li r0, 1
stw r0, 0x7C(r31)
li r0, 0
stw r0, 0x44(r31)
lfs f3, 0x24(r12)
cmpwi r8, 0
bne _presentation2DesiredFraction
