addi r11, r11, _boatState@l
lwz r0, 0x7C(r31)
lwz r8, 8(r11)
and r0, r0, r8
stw r0, 0x40(r12)
li r0, 0
stw r0, 0x44(r12)
lwz r8, 0x40(r31)
cmpwi r8, 1
