stw r0, 0x10(r12)
stw r0, 0x1C(r12)
stw r0, 0x20(r12)
lfs f0, 0x28(r12)
stfs f0, 0x14(r12)
lis r11, _dungeonState@ha
addi r11, r11, _dungeonState@l
lwz r0, 0x10(r11)
cmpwi r0, 0
bne _presentationDungeon
lwz r0, 0x2C(r31)
cmpwi r0, 0
bne _presentationIsland
lwz r0, 0x4C(r31)
cmpwi r0, 2
beq _presentationIsland
# Genuine HUD/native suppression invalidates pending resize ownership too.
lis r11, _familySizeState@ha
addi r11, r11, _familySizeState@l
li r0, 0
stw r0, 4(r11)
stw r0, 0x14(r11)
blr
_presentationIsland:
li r0, 1
stw r0, 0x10(r12)
lwz r8, 0x7C(r31)
stw r8, 0x38(r12)
cmpwi r8, 0
bne _presentationIslandArt
stw r0, 0x30(r12)
lwz r0, 0x10(r31)
stw r0, 0x34(r12)
_presentationIslandArt:
lwz r8, 8(r31)
cmpwi r8, 0
beqlr
lbz r0, 0x44(r8)
andi. r0, r0, 1
beqlr # actual final island visibility, after marine cleanup
lfs f0, 0x64(r31)
lfs f1, 0x70(r31)
lwz r8, 4(r31)
lwz r0, 0x144(r8)
cmplwi r0, 2
blt _presentationFraction
lfs f1, 0x74(r31)
b _presentationFraction
_presentationDungeon:
li r0, 2
stw r0, 0x10(r12)
lwz r8, 0x7C(r31)
stw r8, 0x38(r12)
cmpwi r8, 0
bne _presentationDungeonArt
stw r0, 0x30(r12)
lwz r0, 0x14(r11)
stw r0, 0x34(r12)
_presentationDungeonArt:
lwz r0, 0x14(r11)
lwz r8, 0x44(r11)
or r0, r0, r8
cmpwi r0, 0
beqlr
lfs f0, 0x3C(r11)
lfs f1, 0x34(r11)
lfs f2, 0x2C(r12)
fadds f1, f1, f2
fneg f1, f1
_presentationFraction:
