lwz r8, 0x10(r11)
cmpwi r8, 0
beqlr
lbz r0, 0x44(r8)
andi. r0, r0, 1
stw r0, 0x20(r12)
bne _presentationGeometry
lwz r0, 0x18(r11)
cmpwi r0, 0
