# Only continue an already captured treasure exit in the same live sea HUD.
# The caller checked exit ownership first. No chart/map eligibility is granted.
# Reject ending/other stages and pause before reading the current heart layout.
_boatExitHudEligible:
li r3, 0
lis r8, 0x1047
lwz r8, 0x41E4(r8)
lis r9, 0x7365
ori r9, r9, 0x6100 # sea\0
cmpw r8, r9
bnelr
lbz r0, 0xA7(r30)
cmpwi r0, 0
bnelr
lwz r8, 0x4C(r30)
cmpwi r8, 0
beqlr
lwz r8, 0(r8)
cmpwi r8, 0
beqlr
lwz r8, 0x44(r8)
cmpwi r8, 0
beqlr
lwz r8, 4(r8)
cmpwi r8, 0
beqlr
lwz r8, 0x0C(r8)
cmpwi r8, 0
beqlr
lwz r8, 0x14(r8)
cmpwi r8, 0
beqlr
lbz r0, 0x44(r8)
andi. r0, r0, 1
beqlr
lbz r0, 0x45(r8)
cmpwi r0, 0
beqlr
li r3, 1
blr

# A live sage is selected through the native dungeon-context getter.
# Do not assume a generic partner slot: Medli and Makar use different native
# references. Compare identity with the current controlled player, never retain
# or dereference an actor pointer across HUD ticks, and reject other stages.
_sageFocusControlled:
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
lis r8, 0x1047
lwz r9, 0x41E4(r8)
lis r10, 0x4D5F
ori r10, r10, 0x4461
cmpw r9, r10
beq _sageFocusEarthStage
lis r10, 0x6B61
ori r10, r10, 0x7A65
cmpw r9, r10
bne _sageFocusNone
lwz r9, 0x41E8(r8)
cmpwi r9, 0
bne _sageFocusNone
b _sageFocusStageReady
_sageFocusEarthStage:
lwz r9, 0x41E8(r8)
lis r10, 0x6900
cmpw r9, r10
bne _sageFocusNone
_sageFocusStageReady:
lwz r9, 0x4BE4(r8) # stable Link reference
cmpwi r9, 0
beq _sageFocusNone
lwz r10, 0x4BDC(r8) # currently controlled actor
cmpwi r10, 0
beq _sageFocusNone
cmpw r9, r10
beq _sageFocusNone
bl 0x02657074
cmpwi r3, 0
beq _sageFocusNone
lis r8, 0x1047
lwz r9, 0x4BDC(r8)
cmpw r3, r9
bne _sageFocusNone
lwz r10, 0x4BE4(r8)
cmpwi r10, 0
beq _sageFocusNone
cmpw r3, r10
beq _sageFocusNone
b _sageFocusReturn
_sageFocusNone:
li r3, 0
_sageFocusReturn:
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
blr

# r3: independently owned dungeon map; caller r31: private dungeon state.
# Preserve the ordinary Link call order exactly. Only a verified controlled
# sage uses fresh native markers before native zoom and the single renderer
# tick. The private discovery commit always remains AFTER that renderer tick.
_sageDungeonPresent:
mflr r0
stwu r1, -0x30(r1)
stw r0, 0x34(r1)
stw r30, 0x28(r1)
stw r31, 0x2C(r1)
mr r30, r31
mr r31, r3
bl _airFloorBegin
mr r3, r31
bl _sageFocusControlled
cmpwi r3, 0
bne _airFloorOriginalSage
mr r3, r31
bl _airFloorLinkEligible
cmpwi r3, 0
beq _sagePresentLink
stw r3, 8(r1) # 1 airborne, 2 one-or-more fresh release frames
mr r3, r31
bl 0x02656F34
mr r3, r31
lwz r4, 8(r1)
bl _airFloorSelect
mr r3, r31
bl 0x02657AA0
mr r3, r31
bl _airFloorPublish
lwz r0, 0x1C(r30)
cmpwi r0, 0
beq _airFloorRenderer
mr r3, r31
bl 0x0265B768
_airFloorRenderer:
mr r3, r31
lwz r4, 0x1C(r30)
bl _floorScrollBefore
bl _sageZoomFloorHandoff
mr r3, r31
bl 0x02656FD0
mr r3, r31
bl 0x02657AEC
b _sagePresentAdvance
_airFloorOriginalSage:
mr r3, r31
bl 0x02656F34
# Native projection refreshes Link and sage floors independently. Keep Link's
# +31C/+31D intact; select only display +3D0 and the private renderer target.
lwz r9, 0x920(r31)
cmpwi r9, 0
beq _sagePresentPublish
lbz r0, 0x338(r31)
cmplwi r0, 0x7E
blt _sagePresentPublish
cmplwi r0, 0x88
bge _sagePresentPublish
stb r0, 0x3D0(r31)
stb r0, 0x4BC(r9)
_sagePresentPublish:
mr r3, r31
bl _airFloorSageEligible
cmpwi r3, 0
beq _airFloorSagePublish
mr r4, r3
mr r3, r31
bl _airFloorSelect
_airFloorSagePublish:
mr r3, r31
bl 0x02657AA0
lwz r0, 0x1C(r30)
cmpwi r0, 0
beq _sagePresentRenderer
mr r3, r31
bl 0x0265B768
_sagePresentRenderer:
mr r3, r31
lwz r4, 0x1C(r30)
bl _floorScrollBefore
bl _sageZoomFloorHandoff
mr r3, r31
bl 0x02656FD0
mr r3, r31
bl 0x02657AEC
b _sagePresentAdvance
_sagePresentLink:
lwz r0, 0x1C(r30)
cmpwi r0, 0
beq _sagePresentLinkProjection
mr r3, r31
bl 0x0265B768
_sagePresentLinkProjection:
mr r3, r31
bl 0x02656F34
mr r3, r31
lwz r4, 0x1C(r30)
bl _floorScrollBefore
bl _sageZoomFloorHandoff
mr r3, r31
bl 0x02656FD0
mr r3, r31
bl 0x02657AF4
_sagePresentAdvance:
mr r3, r31
bl 0x02657B44
mr r3, r31
lwz r4, 0x1C(r30)
bl _sageFocusSyncZoom
mr r3, r31
bl _airFloorRestoreSageReference
lwz r30, 0x28(r1)
lwz r31, 0x2C(r1)
lwz r0, 0x34(r1)
mtlr r0
addi r1, r1, 0x30
blr

# The menu's Scroll state deliberately resets rotation and floor zoom. A
# private live focus change must retain its already zoomed pose instead.
# Transfer the complete selected-floor geometry before consuming the floor
# edge, then let the existing native zoom/centering state run exactly once.
# r3: owned map; r4: requested zoom. No actor pointer or native menu is changed.
_sageZoomFloorHandoff:
mflr r0
stwu r1, -0x50(r1)
stw r0, 0x54(r1)
stmw r28, 0x40(r1)
mr r28, r3
cmpwi r4, 0
beq _sageHandoffDone
mr r3, r28
bl _airFloorScope
cmpwi r3, 0
bne _sageHandoffStageReady
lis r8, 0x1047
lwz r9, 0x41E4(r8)
lis r10, 0x4D5F
ori r10, r10, 0x4461
cmpw r9, r10
beq _sageHandoffEarth
lis r10, 0x6B61
ori r10, r10, 0x7A65
cmpw r9, r10
bne _sageHandoffDone
lwz r9, 0x41E8(r8)
cmpwi r9, 0
bne _sageHandoffDone
b _sageHandoffStageReady
_sageHandoffEarth:
lwz r9, 0x41E8(r8)
lis r10, 0x6900
cmpw r9, r10
bne _sageHandoffDone
_sageHandoffStageReady:
lis r8, 0x1047
lwz r9, 0x4BE4(r8)
cmpwi r9, 0
beq _sageHandoffDone
lwz r31, 0x920(r28)
cmpwi r31, 0
beq _sageHandoffDone
lbz r9, 0x4BC(r31)
lbz r10, 0x4BD(r31)
cmpw r9, r10
beq _sageHandoffDone
addi r3, r31, 0x18
bl 0x02006478
cmpwi r3, 0
beq _sageHandoffDone
lwz r8, 0(r3)
lis r9, 0x1049
lwz r9, 0x6078(r9)
cmpw r8, r9
beq _sageHandoffStateReady
lis r9, 0x1049
lwz r9, 0x6108(r9)
cmpw r8, r9
beq _sageHandoffStateReady
lis r9, 0x1049
lwz r9, 0x6048(r9)
cmpw r8, r9
beq _sageHandoffStateReady
lis r9, 0x1049
lwz r9, 0x6138(r9)
cmpw r8, r9
bne _sageHandoffDone
_sageHandoffStateReady:
mr r3, r31
lbz r4, 0x4BD(r31)
bl 0x0267DD18
cmpwi r3, 0
beq _sageHandoffDone
mr r30, r3
lbz r9, 0x58(r30)
lbz r10, 0x4BD(r31)
cmpw r9, r10
bne _sageHandoffDone
mr r3, r31
lbz r4, 0x4BC(r31)
bl 0x0267DD18
cmpwi r3, 0
beq _sageHandoffDone
mr r29, r3
cmpw r29, r30
beq _sageHandoffDone
lbz r9, 0x58(r29)
lbz r10, 0x4BC(r31)
cmpw r9, r10
bne _sageHandoffDone
lfs f0, 0x2C(r30)
lfs f1, 0x4E0(r31)
fcmpu cr0, f0, f1
ble _sageHandoffDone # a full-view pose has no zoom geometry to preserve
mr r3, r31
addi r4, r1, 0x10
addi r5, r1, 0x18
lbz r6, 0x4BC(r31)
bl 0x0267E04C
# Transfer actual pan, inverse center and scale, including partial zoom.
lwz r9, 0x18(r30)
stw r9, 0x18(r29)
lwz r9, 0x1C(r30)
stw r9, 0x1C(r29)
lwz r9, 0x20(r30)
stw r9, 0x20(r29)
lwz r9, 0x24(r30)
stw r9, 0x24(r29)
lwz r9, 0x2C(r30)
stw r9, 0x2C(r29)
lfs f0, 0x4E0(r31)
stfs f0, 0x2C(r30)
li r0, 0
stw r0, 0x20(r30)
stw r0, 0x24(r30)
lwz r9, 0x18(r1)
stw r9, 0x49C(r31)
lwz r9, 0x1C(r1)
stw r9, 0x4A0(r31)
lbz r9, 0x4BC(r31)
stb r9, 0x4BD(r31)
stb r9, 0x4BE(r31)
mr r3, r31
bl 0x0267F2E4
li r3, 1
b _sageHandoffRestore
_sageHandoffDone:
li r3, 0
_sageHandoffRestore:
lmw r28, 0x40(r1)
lwz r0, 0x54(r1)
mtlr r0
addi r1, r1, 0x50
blr

# A native floor-scroll always settles in ZoomOut. Separately, the native
# ToZoomIn callback can consult the original menu's selected marker/floor and
# settle in static ZoomIn. Reconcile only settled states on this private map.
# Never interrupt Scroll/ToZoom/centering animations or restart them per tick.
# r3: owned map; r4: remembered private zoom preference.
_sageFocusSyncZoom:
mflr r0
stwu r1, -0x20(r1)
stw r0, 0x24(r1)
stw r30, 0x18(r1)
stw r31, 0x1C(r1)
mr r31, r3
mr r30, r4
mr r3, r31
bl _airFloorScope
cmpwi r3, 0
bne _sageSyncStageReady
lis r8, 0x1047
lwz r9, 0x41E4(r8)
lis r10, 0x4D5F
ori r10, r10, 0x4461
cmpw r9, r10
beq _sageSyncEarth
lis r10, 0x6B61
ori r10, r10, 0x7A65
cmpw r9, r10
bne _sageSyncDone
lwz r9, 0x41E8(r8)
cmpwi r9, 0
bne _sageSyncDone
b _sageSyncStageReady
_sageSyncEarth:
lwz r9, 0x41E8(r8)
lis r10, 0x6900
cmpw r9, r10
bne _sageSyncDone
_sageSyncStageReady:
lis r8, 0x1047
lwz r9, 0x4BE4(r8)
cmpwi r9, 0
beq _sageSyncDone
lwz r3, 0x920(r31)
cmpwi r3, 0
beq _sageSyncDone
addi r3, r3, 0x18
bl 0x02006478
cmpwi r3, 0
beq _sageSyncDone
lwz r8, 0(r3) # native state ID; compare runtime descriptor IDs, not constants
cmpwi r30, 0
beq _sageSyncWantFull
lis r9, 0x1049
lwz r9, 0x60D8(r9)
cmpw r8, r9
beq _sageSyncEnter
lis r9, 0x1049
lwz r9, 0x6078(r9)
cmpw r8, r9
bne _sageSyncDone
mr r3, r31
bl 0x026568CC # private selected-marker predicate and native camera motion
b _sageSyncDone
_sageSyncEnter:
mr r3, r31
bl 0x0265B828
b _sageSyncDone
_sageSyncWantFull:
lis r9, 0x1049
lwz r9, 0x6078(r9)
cmpw r8, r9
beq _sageSyncExit
lis r9, 0x1049
lwz r9, 0x6108(r9)
cmpw r8, r9
bne _sageSyncDone
_sageSyncExit:
mr r3, r31
bl 0x0265B91C
_sageSyncDone:
lwz r30, 0x18(r1)
lwz r31, 0x1C(r1)
lwz r0, 0x24(r1)
mtlr r0
addi r1, r1, 0x20
blr

# Screen coordinates use NW4F's upward-positive Y. Ascending therefore
# slides both plans toward negative Y (down on the TV); descending reverses it.
_floorScrollState:
.int 0, 0, 0, 0 # owner, renderer, exact stage words
.int -1, -1, -1, 0 # dungeon, previous display/Link floors, active
.int 0, 0, 0 # outgoing/incoming floors, start tick
.float 0, 0, 0, 0 # direction, distance, outgoing/incoming screen Y
.int 0 # last presented floor pane (identity only; re-resolved before use)
.float 1, 0, 0, 0, 1, 0 # last actual final affine pose
.float 1, 0, 0, 0, 1, 0 # frozen outgoing affine pose
.float 1, 0, 0, 0, 1, 0 # outgoing affine correction
.float 18646875 # 300 ms, using the existing 62,156,250 Hz HUD clock
.float 1, 0, 0.00000001, 2.2, -1

_floorScrollInvalidate:
lis r8, _floorScrollState@ha
addi r8, r8, _floorScrollState@l
li r0, 0
stw r0, 0(r8)
stw r0, 0x1C(r8)
blr

# Called once as the final HUD operation. A title/loading/menu HUD must not
# initialize or dereference a private dungeon map outside its native gate.
_floorScrollHudFinal:
lis r8, _dungeonState@ha
addi r8, r8, _dungeonState@l
lwz r0, 0x0C(r8)
cmpwi r0, 1
bnelr
lwz r0, 0x10(r8)
cmpwi r0, 0
beqlr
lwz r9, 0x14(r8)
lwz r0, 0x44(r8)
or r0, r0, r9
cmpwi r0, 0
beq _floorScrollInvalidate # fully hidden: do not retain an old visible pose
lwz r3, 4(r8)
cmpwi r3, 0
beqlr
b _floorScrollPresent

# r3 owned map -> renderer or zero. Never enter other scenes or menu layouts.
_floorScrollNativeEligible:
lis r8, 0x1047
lwz r9, 0x4BE4(r8)
cmpwi r9, 0
beq _floorScrollIneligible
lwz r9, 0x41E4(r8)
lis r10, 0x4D5F
ori r10, r10, 0x4461
cmpw r9, r10
beq _floorScrollEarth
lis r10, 0x6B61
ori r10, r10, 0x7A65
cmpw r9, r10
bne _floorScrollIneligible
lwz r9, 0x41E8(r8)
cmpwi r9, 0
bne _floorScrollIneligible
b _floorScrollStageReady
_floorScrollEarth:
lwz r9, 0x41E8(r8)
lis r10, 0x6900
cmpw r9, r10
bne _floorScrollIneligible
_floorScrollStageReady:
lwz r3, 0x920(r3)
cmpwi r3, 0
beqlr
lwz r9, 0x4B8(r3)
cmpwi r9, 0
beq _floorScrollIneligible
lwz r9, 0x0C(r9)
cmplwi r9, 10
bgt _floorScrollIneligible
cmpwi r9, 0
bnelr
_floorScrollIneligible:
li r3, 0
blr

# r3 map, r4 renderer -> boolean. No stale pointers survive scene ownership.
_floorScrollSameContext:
lis r8, _floorScrollState@ha
addi r8, r8, _floorScrollState@l
lwz r9, 0(r8)
cmpw r3, r9
bne _floorScrollContextNo
lwz r9, 4(r8)
cmpw r4, r9
bne _floorScrollContextNo
lis r10, 0x1047
